{
  "name": "PM Master: IT Project Management & Automation Hub",
  "description": "A comprehensive IT PM tool for managing multiple projects with automated templates for charters, weekly reports, and retrospectives, featuring interactive Gantt, Calendar, and List views."
}

export type StatusDepth1 = 'TODO' | 'IN_PROGRESS' | 'DONE';

export interface Project {
  id: string;
  name: string;
  manager: string;
  description: string;
  status1: StatusDepth1;
  status2: string; // Dynamic 2nd depth status
  startDate: string;
  endDate: string;
  milestones: Milestone[];
  charter?: string;
  requirements?: string;
  weeklyReports: WeeklyReport[];
  retrospective?: string;
}

export interface Milestone {
  id: string;
  title: string;
  startDate: string;
  endDate: string;
  status: 'UPCOMING' | 'COMPLETED' | 'OVERDUE';
}

export interface WeeklyReport {
  id: string;
  date: string;
  content: string;
}

export type ViewType = 'LIST' | 'CALENDAR' | 'GANTT';
export type ScaleType = 'DAY' | 'MONTH' | 'QUARTER' | 'YEAR';

export interface AppState {
  projects: Project[];
  customStatus2: string[];
  selectedProjectId: string | null;
  activeView: 'DASHBOARD' | 'PROJECT_DETAIL' | 'SETTINGS';
}

import React from 'react';
import { StatusDepth1 } from './types';

export const INITIAL_STATUS2 = [
  '준비중',
  '요구사항취합',
  '킥오프',
  '기획',
  '개발',
  'QA',
  '보안검수',
  '오픈'
];

export const STATUS1_COLORS: Record<StatusDepth1, string> = {
  TODO: 'bg-slate-200 text-slate-700',
  IN_PROGRESS: 'bg-blue-100 text-blue-700',
  DONE: 'bg-green-100 text-green-700'
};

export const MOCK_PROJECTS = [
  {
    id: '1',
