import React from 'react';
import { Project } from '../types';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, PieChart, Pie, Cell } from 'recharts';
import { STATUS1_COLORS } from '../constants';

interface DashboardProps {
  projects: Project[];
  onSelect: (id: string) => void;
}

export const Dashboard: React.FC<DashboardProps> = ({ projects, onSelect }) => {
  const stats = {
    total: projects.length,
    todo: projects.filter(p => p.status1 === 'TODO').length,
    inProgress: projects.filter(p => p.status1 === 'IN_PROGRESS').length,
    done: projects.filter(p => p.status1 === 'DONE').length,
  };

  const chartData = [
    { name: 'TODO', value: stats.todo },
    { name: 'In Progress', value: stats.inProgress },
    { name: 'Done', value: stats.done },
  ];

  const COLORS = ['#94a3b8', '#3b82f6', '#22c55e'];

  return (
    <div className="space-y-8 animate-fadeIn">
      <header>
        <h2 className="text-3xl font-bold">전체 프로젝트 대시보드</h2>
        <p className="text-slate-500">통합 프로젝트 진행 상황을 한눈에 파악하세요.</p>
      </header>

      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        {[
          { label: '전체 프로젝트', val: stats.total, color: 'border-slate-300' },
          { label: '대기 중 (TODO)', val: stats.todo, color: 'border-slate-400' },
          { label: '진행 중', val: stats.inProgress, color: 'border-blue-500' },
          { label: '완료', val: stats.done, color: 'border-green-500' },
        ].map((item, i) => (
          <div key={i} className={`bg-white p-6 rounded-xl border-l-4 shadow-sm ${item.color}`}>
            <p className="text-sm text-slate-500 font-medium">{item.label}</p>
            <p className="text-3xl font-bold mt-1">{item.val}</p>
          </div>
        ))}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200 h-[350px]">
          <h3 className="font-semibold mb-6">프로젝트 상태 분포</h3>
          <ResponsiveContainer width="100%" height="100%">
            <BarChart data={chartData}>
              <CartesianGrid strokeDasharray="3 3" vertical={false} />
              <XAxis dataKey="name" />
              <YAxis />
              <Tooltip />
              <Bar dataKey="value">
                {chartData.map((entry, index) => (
                  <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                ))}
              </Bar>
            </BarChart>
          </ResponsiveContainer>
        </div>

        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200 overflow-y-auto max-h-[350px]">
          <h3 className="font-semibold mb-4">최근 활성 프로젝트</h3>
          <div className="space-y-3">
            {projects.map(p => (
              <div 
                key={p.id}
                onClick={() => onSelect(p.id)}
                className="group p-4 rounded-lg border border-slate-100 hover:border-blue-300 cursor-pointer transition-all hover:shadow-md"
              >
                <div className="flex justify-between items-center">
                  <span className="font-medium group-hover:text-blue-600 transition-colors">{p.name}</span>
                  <span className={`text-[10px] px-2 py-0.5 rounded-full font-bold uppercase ${STATUS1_COLORS[p.status1]}`}>
                    {p.status1}
                  </span>
                </div>
                <div className="flex justify-between mt-2 text-xs text-slate-400">
                  <span>PM: {p.manager}</span>
                  <span>상태: {p.status2}</span>
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { Project, Milestone, ViewType, ScaleType } from '../types';
import { MilestoneView } from './MilestoneView';
import { generateTemplate } from '../services/geminiService';
import { STATUS1_COLORS } from '../constants';

interface ProjectDetailProps {
  project: Project;
  onUpdate: (updated: Project) => void;
  status2Options: string[];
}

export const ProjectDetail: React.FC<ProjectDetailProps> = ({ project, onUpdate, status2Options }) => {
  const [activeTab, setActiveTab] = useState<'OVERVIEW' | 'MILESTONES' | 'CHARTER' | 'REPORT' | 'RETRO'>('OVERVIEW');
  const [isGenerating, setIsGenerating] = useState(false);
  const [showMilestoneModal, setShowMilestoneModal] = useState(false);

  const handleStatusChange = (field: 'status1' | 'status2', val: string) => {
    onUpdate({ ...project, [field]: val });
  };

  const handleAutoGenerate = async (type: any) => {
    setIsGenerating(true);
    const content = await generateTemplate(type, {
      name: project.name,
      description: project.description,
      status: `${project.status1} / ${project.status2}`
    });

    const fieldMap: any = {
      CHARTER: 'charter',
      REQUIREMENTS: 'requirements',
      RETROSPECTIVE: 'retrospective'
    };

    if (type === 'WEEKLY_REPORT') {
      const newReport = { id: Date.now().toString(), date: new Date().toISOString().split('T')[0], content };
      onUpdate({ ...project, weeklyReports: [newReport, ...project.weeklyReports] });
    } else {
      onUpdate({ ...project, [fieldMap[type]]: content });
    }
    setIsGenerating(false);
  };

  return (
    <div className="space-y-6 animate-fadeIn">
      {/* Header */}
      <div className="flex justify-between items-start bg-white p-6 rounded-xl border border-slate-200 shadow-sm">
        <div>
          <div className="flex items-center gap-3 mb-2">
            <h2 className="text-2xl font-bold">{project.name}</h2>
            <span className={`px-3 py-1 rounded-full text-xs font-bold ${STATUS1_COLORS[project.status1]}`}>
              {project.status1}
            </span>
          </div>
          <p className="text-slate-500 text-sm max-w-2xl">{project.description}</p>
        </div>
        <div className="flex flex-col gap-2 min-w-[200px]">
          <label className="text-xs font-semibold text-slate-400 uppercase">현재 프로세스</label>
          <select 
            value={project.status2} 
            onChange={(e) => handleStatusChange('status2', e.target.value)}
            className="w-full p-2 text-sm border border-slate-200 rounded-lg bg-slate-50 focus:ring-2 focus:ring-blue-500 outline-none"
          >
            {status2Options.map(opt => <option key={opt} value={opt}>{opt}</option>)}
          </select>
        </div>
      </div>

      {/* Tabs */}
      <div className="flex border-b border-slate-200">
        {[
          { id: 'OVERVIEW', label: '개요', icon: '📝' },
          { id: 'MILESTONES', label: '마일스톤', icon: '📅' },
          { id: 'CHARTER', label: 'Project Charter', icon: '📜' },
          { id: 'REPORT', label: '주간 보고', icon: '📊' },
          { id: 'RETRO', label: '회고', icon: '💡' },
        ].map(tab => (
          <button
            key={tab.id}
            onClick={() => setActiveTab(tab.id as any)}
            className={`px-6 py-3 text-sm font-medium border-b-2 transition-colors flex items-center gap-2 ${
              activeTab === tab.id ? 'border-blue-600 text-blue-600' : 'border-transparent text-slate-400 hover:text-slate-600'
            }`}
          >
            <span>{tab.icon}</span> {tab.label}
          </button>
        ))}
      </div>

      {/* Content Area */}
      <div className="min-h-[500px]">
        {activeTab === 'OVERVIEW' && (
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm">
              <h3 className="font-semibold mb-4 flex justify-between items-center">
                상세 정보
                <button 
                  onClick={() => handleAutoGenerate('REQUIREMENTS')}
                  className="text-xs text-blue-600 hover:underline"
                  disabled={isGenerating}
                >
                  {isGenerating ? '생성 중...' : '✨ 요구사항 AI 생성'}
                </button>
              </h3>
              <div className="prose prose-sm max-w-none text-slate-600">
                {project.requirements ? (
                  <div className="whitespace-pre-wrap bg-slate-50 p-4 rounded-lg border border-slate-100">{project.requirements}</div>
                ) : (
                  <p className="italic text-slate-400">요구사항 내용이 없습니다. AI 생성을 이용해보세요.</p>
                )}
              </div>
            </div>
            <div className="space-y-6">
              <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm">
                <h3 className="font-semibold mb-4">주요 마일스톤 현황</h3>
                <div className="space-y-2">
                   {project.milestones.slice(0, 3).map(m => (
                     <div key={m.id} className="flex justify-between items-center p-3 bg-slate-50 rounded-lg text-sm">
                       <span>{m.title}</span>
                       <span className="text-slate-400 text-xs">{m.endDate}</span>
                     </div>
                   ))}
                   <button onClick={() => setActiveTab('MILESTONES')} className="w-full text-center text-xs text-blue-600 mt-2">전체 보기</button>
                </div>
              </div>
            </div>
          </div>
        )}

        {activeTab === 'MILESTONES' && (
          <MilestoneView 
            milestones={project.milestones} 
            onAdd={(m) => onUpdate({...project, milestones: [...project.milestones, m]})} 
          />
        )}

        {activeTab === 'CHARTER' && (
           <div className="bg-white p-8 rounded-xl border border-slate-200 shadow-sm max-w-4xl mx-auto">
             <div className="flex justify-between items-center mb-6">
               <h3 className="text-xl font-bold">Project Charter</h3>
               <button 
                 onClick={() => handleAutoGenerate('CHARTER')}
                 className="px-4 py-2 bg-blue-600 text-white text-sm rounded-lg hover:bg-blue-700 disabled:bg-slate-300"
                 disabled={isGenerating}
               >
                 {isGenerating ? 'AI가 작성 중...' : '✨ AI 자동 생성'}
               </button>
             </div>
             <div className="prose max-w-none">
                {project.charter ? (
                  <div className="p-6 bg-slate-50 border border-slate-100 rounded-xl font-mono text-sm leading-relaxed whitespace-pre-wrap">{project.charter}</div>
                ) : (
                  <div className="text-center py-20 text-slate-400 border-2 border-dashed border-slate-200 rounded-xl">
                    아직 생성된 Charter가 없습니다. AI 버튼을 클릭하세요.
                  </div>
                )}
             </div>
           </div>
        )}

        {activeTab === 'REPORT' && (
           <div className="space-y-6">
             <div className="flex justify-between items-center">
                <h3 className="text-xl font-bold">주간 활동 보고</h3>
                <button 
                  onClick={() => handleAutoGenerate('WEEKLY_REPORT')}
                  className="px-4 py-2 bg-slate-900 text-white text-sm rounded-lg hover:bg-black"
                  disabled={isGenerating}
                >
                  {isGenerating ? '보고서 작성 중...' : '✨ 신규 주간 보고 생성'}
                </button>
             </div>
             <div className="grid gap-4">
                {project.weeklyReports.map(report => (
                  <div key={report.id} className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm">
                    <div className="flex justify-between items-center mb-4 pb-2 border-b border-slate-100">
                      <span className="font-bold text-slate-900">{report.date} 주간 보고</span>
                      <span className="text-xs text-slate-400">작성자: {project.manager}</span>
                    </div>
                    <div className="text-sm text-slate-600 whitespace-pre-wrap">{report.content}</div>
                  </div>
                ))}
                {project.weeklyReports.length === 0 && (
                  <div className="text-center py-20 bg-white rounded-xl border border-dashed border-slate-300 text-slate-400">
                    리포트 내역이 없습니다.
                  </div>
                )}
             </div>
           </div>
        )}

        {activeTab === 'RETRO' && (
           <div className="bg-white p-8 rounded-xl border border-slate-200 shadow-sm max-w-4xl mx-auto">
             <div className="flex justify-between items-center mb-6">
               <h3 className="text-xl font-bold">프로젝트 회고 (Post-mortem)</h3>
               <button 
                 onClick={() => handleAutoGenerate('RETROSPECTIVE')}
                 className="px-4 py-2 bg-green-600 text-white text-sm rounded-lg hover:bg-green-700"
                 disabled={isGenerating}
               >
                 {isGenerating ? '분석 중...' : '✨ AI 회고 생성'}
               </button>
             </div>
             <div className="prose max-w-none">
                {project.retrospective ? (
                  <div className="p-6 bg-slate-50 border border-slate-100 rounded-xl text-sm leading-relaxed whitespace-pre-wrap">{project.retrospective}</div>
                ) : (
                  <div className="text-center py-20 text-slate-400 border-2 border-dashed border-slate-200 rounded-xl">
                    프로젝트 완료 후 회고를 작성하거나 AI에게 요청하세요.
                  </div>
                )}
             </div>
           </div>
        )}
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { Milestone, ViewType, ScaleType } from '../types';

interface MilestoneViewProps {
  milestones: Milestone[];
  onAdd: (m: Milestone) => void;
}

export const MilestoneView: React.FC<MilestoneViewProps> = ({ milestones, onAdd }) => {
  const [view, setView] = useState<ViewType>('LIST');
  const [scale, setScale] = useState<ScaleType>('MONTH');
  const [showAdd, setShowAdd] = useState(false);
  const [newTitle, setNewTitle] = useState('');
  const [newStart, setNewStart] = useState('');
  const [newEnd, setNewEnd] = useState('');

  const handleAdd = () => {
    if (!newTitle || !newStart || !newEnd) return;
    onAdd({
      id: Math.random().toString(36).substr(2, 9),
      title: newTitle,
      startDate: newStart,
      endDate: newEnd,
      status: 'UPCOMING'
    });
    setShowAdd(false);
    setNewTitle('');
    setNewStart('');
    setNewEnd('');
  };

  return (
    <div className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden">
      <div className="p-4 border-b border-slate-100 flex flex-wrap justify-between items-center gap-4 bg-slate-50/50">
        <div className="flex gap-2 p-1 bg-slate-200/50 rounded-lg">
          {(['LIST', 'CALENDAR', 'GANTT'] as ViewType[]).map(v => (
            <button
              key={v}
              onClick={() => setView(v)}
              className={`px-4 py-1.5 text-xs font-bold rounded-md transition-all ${
                view === v ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500 hover:text-slate-800'
              }`}
            >
              {v}
            </button>
          ))}
        </div>

        {view === 'GANTT' && (
          <div className="flex gap-1">
            {(['DAY', 'MONTH', 'QUARTER', 'YEAR'] as ScaleType[]).map(s => (
              <button
                key={s}
                onClick={() => setScale(s)}
                className={`px-3 py-1 text-[10px] rounded border ${
                  scale === s ? 'bg-slate-900 text-white border-slate-900' : 'bg-white text-slate-500 border-slate-200 hover:bg-slate-50'
                }`}
              >
                {s}
              </button>
            ))}
          </div>
        )}

        <button 
          onClick={() => setShowAdd(true)}
          className="px-4 py-1.5 bg-blue-600 text-white text-xs font-bold rounded-lg hover:bg-blue-700 flex items-center gap-2"
        >
          <span>+</span> New Milestone
        </button>
      </div>

      <div className="p-6 overflow-x-auto min-h-[400px]">
        {view === 'LIST' && (
          <table className="w-full text-left">
            <thead>
              <tr className="text-xs text-slate-400 uppercase tracking-wider">
                <th className="pb-4 font-semibold">마일스톤명</th>
                <th className="pb-4 font-semibold">시작일</th>
                <th className="pb-4 font-semibold">종료일</th>
                <th className="pb-4 font-semibold">상태</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {milestones.map(m => (
                <tr key={m.id} className="text-sm group hover:bg-slate-50 transition-colors">
                  <td className="py-4 font-medium">{m.title}</td>
                  <td className="py-4 text-slate-500">{m.startDate}</td>
                  <td className="py-4 text-slate-500">{m.endDate}</td>
                  <td className="py-4">
                    <span className={`px-2 py-0.5 rounded-full text-[10px] font-bold ${
                      m.status === 'COMPLETED' ? 'bg-green-100 text-green-700' : 
                      m.status === 'OVERDUE' ? 'bg-red-100 text-red-700' : 'bg-blue-100 text-blue-700'
                    }`}>
                      {m.status}
                    </span>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}

