import React, { useState } from 'react';

interface SettingsProps {
  customStatus2: string[];
  onUpdate: (newList: string[]) => void;
}

export const Settings: React.FC<SettingsProps> = ({ customStatus2, onUpdate }) => {
  const [newStatus, setNewStatus] = useState('');

  const handleAdd = () => {
    if (newStatus && !customStatus2.includes(newStatus)) {
      onUpdate([...customStatus2, newStatus]);
      setNewStatus('');
    }
  };

  const handleRemove = (status: string) => {
    onUpdate(customStatus2.filter(s => s !== status));
  };

  return (
    <div className="max-w-2xl mx-auto space-y-8 animate-fadeIn">
      <header>
        <h2 className="text-3xl font-bold">워크플로우 설정</h2>
        <p className="text-slate-500">프로젝트의 상세 단계(2depth status)를 조직의 프로세스에 맞게 커스텀하세요.</p>
      </header>

      <div className="bg-white p-8 rounded-2xl border border-slate-200 shadow-sm">
        <h3 className="text-sm font-bold text-slate-400 uppercase mb-6">프로세스 단계 (2단계 상태값)</h3>

        <div className="flex gap-2 mb-8">
          <input 
            type="text" 
            value={newStatus}
            onChange={e => setNewStatus(e.target.value)}
            placeholder="새로운 단계 이름 (예: 통합테스트)"
            className="flex-1 p-3 border border-slate-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none"
          />
          <button 
            onClick={handleAdd}
            className="px-6 py-3 bg-slate-900 text-white rounded-xl font-bold hover:bg-black transition-colors"
          >
            추가
          </button>
        </div>

        <div className="space-y-2">
          {customStatus2.map((s, idx) => (
            <div key={idx} className="flex justify-between items-center p-4 bg-slate-50 rounded-xl border border-slate-100 group transition-all hover:border-slate-300">
              <div className="flex items-center gap-4">
                <span className="text-xs font-bold text-slate-300">#{idx + 1}</span>
                <span className="font-medium">{s}</span>
              </div>
              <button 
                onClick={() => handleRemove(s)}
                className="text-slate-300 hover:text-red-500 transition-colors opacity-0 group-hover:opacity-100"
              >
                삭제
              </button>
            </div>
          ))}
        </div>

        <div className="mt-8 p-4 bg-blue-50 border border-blue-100 rounded-xl">
          <p className="text-sm text-blue-700 leading-relaxed">
            💡 <strong>Tip:</strong> 1단계 상태(Todo, In Progress, Done)는 시스템 고정값이며, 위 리스트는 모든 프로젝트의 상세 진행 상황을 추적하는 데 사용됩니다.
          </p>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Sidebar } from './components/Sidebar';
import { Dashboard } from './components/Dashboard';
import { ProjectDetail } from './components/ProjectDetail';
import { Settings } from './components/Settings';
import { AppState, Project } from './types';
import { MOCK_PROJECTS, INITIAL_STATUS2 } from './constants';

const App: React.FC = () => {
  const [state, setState] = useState<AppState>({
    projects: MOCK_PROJECTS as Project[],
    customStatus2: INITIAL_STATUS2,
    selectedProjectId: null,
    activeView: 'DASHBOARD'
  });

  const handleSelectProject = (id: string | null) => {
    setState(prev => ({ 
      ...prev, 
      selectedProjectId: id, 
      activeView: id ? 'PROJECT_DETAIL' : 'DASHBOARD' 
    }));
  };

  const handleNavigate = (view: 'DASHBOARD' | 'SETTINGS') => {
    setState(prev => ({ 
      ...prev, 
      activeView: view, 
      selectedProjectId: null 
    }));
  };

  const handleUpdateProject = (updated: Project) => {
    setState(prev => ({
      ...prev,
      projects: prev.projects.map(p => p.id === updated.id ? updated : p)
    }));
  };

  const handleUpdateStatus2 = (newList: string[]) => {
    setState(prev => ({ ...prev, customStatus2: newList }));
  };

  const selectedProject = state.projects.find(p => p.id === state.selectedProjectId);

  return (
    <div className="min-h-screen bg-slate-50 flex">
      <Sidebar 
        projects={state.projects} 
        selectedId={state.selectedProjectId}
        onSelectProject={handleSelectProject}
        onNavigate={handleNavigate}
      />

      <main className="flex-1 ml-64 p-8 lg:p-12 transition-all duration-300">
        <div className="max-w-7xl mx-auto">
          {state.activeView === 'DASHBOARD' && (
            <Dashboard 
              projects={state.projects} 
              onSelect={handleSelectProject} 
            />
          )}

          {state.activeView === 'PROJECT_DETAIL' && selectedProject && (
            <ProjectDetail 
              project={selectedProject} 
              onUpdate={handleUpdateProject}
              status2Options={state.customStatus2}
            />
          )}

          {state.activeView === 'SETTINGS' && (
            <Settings 
              customStatus2={state.customStatus2} 
              onUpdate={handleUpdateStatus2} 
            />
          )}
        </div>
      </main>

      {/* Persistent Add Project Floating Button */}
      {state.activeView === 'DASHBOARD' && (
        <button 
          onClick={() => {
            const newProj: Project = {
              id: Date.now().toString(),
              name: '신규 프로젝트 ' + (state.projects.length + 1),
              manager: '관리자',
              description: '설명을 입력해주세요.',
              status1: 'TODO',
              status2: state.customStatus2[0],
              startDate: new Date().toISOString().split('T')[0],
              endDate: new Date().toISOString().split('T')[0],
              milestones: [],
              weeklyReports: []
            };
            setState(prev => ({ ...prev, projects: [...prev.projects, newProj] }));
          }}
          className="fixed bottom-10 right-10 w-14 h-14 bg-blue-600 text-white rounded-full shadow-2xl hover:bg-blue-700 flex items-center justify-center text-3xl font-light transition-transform hover:scale-110 active:scale-95"
        >
          +
        </button>
      )}
    </div>
  );
};

export default App;

