                <th className="px-8 py-4">PM</th>
                <th className="px-8 py-4">1단계 상태</th>
                <th className="px-8 py-4">2단계 상세</th>
                <th className="px-8 py-4 text-right">기간</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {projects.map(p => (
                <tr 
                  key={p.id} 
                  onClick={() => onSelect(p.id)}
                  className="group hover:bg-slate-50 cursor-pointer transition-colors"
                >
                  <td className="px-8 py-4">
                    <div className="font-bold text-slate-700 group-hover:text-blue-600 transition-colors">{p.name}</div>
                    <div className="text-xs text-slate-400 line-clamp-1">{p.description}</div>
                  </td>
                  <td className="px-8 py-4 text-sm text-slate-600 font-medium">{p.manager}</td>
                  <td className="px-8 py-4">
                    <span className={`px-2 py-0.5 rounded-full text-[10px] font-black uppercase ${STATUS1_COLORS[p.status1]}`}>
                      {p.status1}
                    </span>
                  </td>
                  <td className="px-8 py-4">
                    <span className="text-xs font-bold text-slate-500 bg-slate-100 px-2 py-1 rounded">
                      {p.status2}
                    </span>
                  </td>
                  <td className="px-8 py-4 text-right">
                    <div className="text-[10px] font-mono text-slate-400">{p.startDate} ~ {p.endDate}</div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

