        {activeTab === 'CHARTER' && (
           <div className="bg-white p-8 rounded-xl border border-slate-200 shadow-sm max-w-4xl mx-auto">
             <div className="flex justify-between items-center mb-6">
               <h3 className="text-xl font-bold">Project Charter</h3>
               <button 
                 onClick={() => handleAutoGenerate('CHARTER')}
                 className="px-4 py-2 bg-blue-600 text-white text-sm rounded-lg hover:bg-blue-700 disabled:bg-slate-300 shadow-md font-bold transition-all"
                 disabled={isGenerating}
               >
                 {isGenerating ? 'AI가 작성 중...' : '✨ AI 자동 생성'}
               </button>
             </div>
             <div className="prose max-w-none">
                {project.charter ? (
                  <div className="p-6 bg-slate-50 border border-slate-100 rounded-xl font-mono text-sm leading-relaxed whitespace-pre-wrap">{project.charter}</div>
