        {activeTab === 'REPORT' && (
           <div className="space-y-6">
             <div className="flex justify-between items-center">
                <h3 className="text-xl font-bold">주간 활동 보고</h3>
                <button 
                  onClick={() => handleAutoGenerate('WEEKLY_REPORT')}
                  className="px-4 py-2 bg-slate-900 text-white text-sm rounded-lg hover:bg-black font-bold shadow-md"
                  disabled={isGenerating}
                >
                  {isGenerating ? '보고서 작성 중...' : '✨ 신규 주간 보고 생성'}
                </button>
             </div>
             <div className="grid gap-4">
                {project.weeklyReports.map(report => (
