  // Gantt 타임라인 헤더 생성을 위한 메모이제이션된 함수
  const timelineUnits = useMemo(() => {
    const units = [];
    const today = new Date();
    const currentYear = today.getFullYear();

    if (scale === 'DAY') {
      for (let i = 0; i < 10; i++) {
        const d = new Date(today);
        d.setDate(today.getDate() + i);
        units.push(`${d.getMonth() + 1}/${d.getDate()}`);
      }
    } else if (scale === 'MONTH') {
      for (let i = 1; i <= 12; i++) {
        units.push(`${i}월`);
      }
    } else if (scale === 'QUARTER') {
      for (let i = 1; i <= 4; i++) {
        units.push(`${i}분기`);
      }
    } else if (scale === 'YEAR') {
      for (let i = -1; i <= 2; i++) {
        units.push(`${currentYear + i}년`);
      }
    }
    return units;
  }, [scale]);

