                  </div>
                  <div className="flex-1 h-8 bg-slate-50 rounded-full relative overflow-hidden gantt-grid border border-slate-100 cursor-pointer shadow-inner" onClick={() => openEditModal(m)}>
                    {/* 눈금선 시뮬레이션 */}
                    <div className="absolute inset-0 flex divide-x divide-slate-200/50 pointer-events-none">
                      {timelineUnits.map((_, i) => <div key={i} className="flex-1 h-full" />)}
