                  type="text" 
                  value={formTitle} 
                  onChange={e => setFormTitle(e.target.value)}
                  className="w-full p-2.5 border border-slate-200 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none text-sm"
                  placeholder="예: 기획서 완료"
