    };
    onUpdateMilestones([...milestones, newMilestone]);
    setShowAdd(false);
  };

  const handleSaveEdit = () => {
    if (!editingMilestone || !formTitle || !formStart || !formEnd) return;
    const updatedList = milestones.map(m => 
      m.id === editingMilestone.id 
        ? { ...m, title: formTitle, startDate: formStart, endDate: formEnd, status: formStatus }
        : m
    );
    onUpdateMilestones(updatedList);
    setEditingMilestone(null);
  };

  const handleDelete = (e: React.MouseEvent, id: string) => {
    e.preventDefault();
    e.stopPropagation();
    if (window.confirm('이 마일스톤을 정말 삭제하시겠습니까?')) {
      const filtered = milestones.filter(m => m.id !== id);
      onUpdateMilestones(filtered);
    }
  };

  // --- Date Helpers ---
  const today = new Date();
  today.setHours(0, 0, 0, 0);

  // Gantt 타임라인 데이터 및 범위 계산
  const ganttConfig = useMemo(() => {
    const units = [];
    let startRange = new Date(today);
    let endRange = new Date(today);

    if (scale === 'DAY') {
      startRange = new Date(today);
      for (let i = 0; i < 10; i++) {
        const d = new Date(today);
        d.setDate(today.getDate() + i);
        units.push(`${d.getMonth() + 1}/${d.getDate()}`);
      }
      endRange.setDate(today.getDate() + 10);
    } else if (scale === 'MONTH') {
      startRange = new Date(today.getFullYear(), 0, 1);
      for (let i = 1; i <= 12; i++) units.push(`${i}월`);
      endRange = new Date(today.getFullYear(), 11, 31);
    } else if (scale === 'QUARTER') {
      startRange = new Date(today.getFullYear(), 0, 1);
      for (let i = 1; i <= 4; i++) units.push(`${i}분기`);
      endRange = new Date(today.getFullYear(), 11, 31);
    } else if (scale === 'YEAR') {
      const startYear = today.getFullYear() - 1;
      startRange = new Date(startYear, 0, 1);
      for (let i = 0; i < 4; i++) units.push(`${startYear + i}년`);
      endRange = new Date(startYear + 3, 11, 31);
    }

    return { units, startRange, endRange };
  }, [scale, today]);

  // Calendar 날짜 배열 생성 (현재 달 1일 기준 35일치)
  const calendarDates = useMemo(() => {
    const startOfMonth = new Date(today.getFullYear(), today.getMonth(), 1);
    const dates = [];
    for (let i = 0; i < 35; i++) {
      const d = new Date(startOfMonth);
      d.setDate(startOfMonth.getDate() + i);
      dates.push(d);
    }
    return dates;
  }, [today]);

  // Gantt 바 위치/너비 계산 함수
  const calculateGanttStyle = (m: Milestone) => {
    const { startRange, endRange } = ganttConfig;
    const mStart = new Date(m.startDate);
    const mEnd = new Date(m.endDate);

    const totalDuration = endRange.getTime() - startRange.getTime();

    // 시작 위치 (%)
    let left = ((mStart.getTime() - startRange.getTime()) / totalDuration) * 100;
    // 너비 (%)
    let width = ((mEnd.getTime() - mStart.getTime()) / totalDuration) * 100;

    // 범위 보정 (타임라인 밖으로 나가는 경우 처리)
    if (left < 0) {
      width = width + left;
      left = 0;
    }
    if (left + width > 100) {
      width = 100 - left;
    }
    if (width < 0) return { display: 'none' };

    return { left: `${left}%`, width: `${width}%` };
  };

  return (
    <div className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden">
      <div className="p-4 border-b border-slate-100 flex flex-wrap justify-between items-center gap-4 bg-slate-50/50">
        <div className="flex gap-2 p-1 bg-slate-200/50 rounded-lg">
          {(['LIST', 'CALENDAR', 'GANTT'] as ViewType[]).map(v => (
            <button
              key={v}
              onClick={() => setView(v)}
              className={`px-4 py-1.5 text-xs font-bold rounded-md transition-all ${
                view === v ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500 hover:text-slate-800'
              }`}
            >
              {v}
            </button>
          ))}
        </div>

        {view === 'GANTT' && (
          <div className="flex gap-1">
            {(['DAY', 'MONTH', 'QUARTER', 'YEAR'] as ScaleType[]).map(s => (
              <button
                key={s}
                onClick={() => setScale(s)}
                className={`px-3 py-1 text-[10px] rounded border ${
                  scale === s ? 'bg-slate-900 text-white border-slate-900' : 'bg-white text-slate-500 border-slate-200 hover:bg-slate-50'
                }`}
              >
                {s}
              </button>
            ))}
          </div>
        )}

        <button 
          onClick={openAddModal}
          className="px-4 py-1.5 bg-blue-600 text-white text-xs font-bold rounded-lg hover:bg-blue-700 flex items-center gap-2 shadow-sm"
        >
          <span>+</span> 마일스톤 추가
        </button>
      </div>

      <div className="p-6 overflow-x-auto min-h-[400px]">
        {view === 'LIST' && (
          <table className="w-full text-left">
            <thead>
              <tr className="text-xs text-slate-400 uppercase tracking-wider">
                <th className="pb-4 font-semibold px-2">마일스톤명</th>
                <th className="pb-4 font-semibold px-2 text-center">기간</th>
                <th className="pb-4 font-semibold px-2 text-center">상태</th>
                <th className="pb-4 font-semibold px-2 text-right">관리</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {milestones.map(m => (
                <tr key={m.id} className="text-sm group hover:bg-slate-50/50 transition-colors">
                  <td className="py-4 font-bold text-slate-700 px-2 cursor-pointer" onClick={() => openEditModal(m)}>{m.title}</td>
                  <td className="py-4 text-slate-500 px-2 text-center text-xs font-mono cursor-pointer" onClick={() => openEditModal(m)}>
                    {m.startDate} ~ {m.endDate}
                  </td>
                  <td className="py-4 px-2 text-center">
                    <span className={`px-2 py-0.5 rounded-full text-[10px] font-bold ${
                      m.status === 'COMPLETED' ? 'bg-green-100 text-green-700' : 
                      m.status === 'OVERDUE' ? 'bg-red-100 text-red-700' : 'bg-blue-100 text-blue-700'
                    }`}>
                      {m.status}
                    </span>
                  </td>
                  <td className="py-4 px-2 text-right space-x-1">
                    <div className="opacity-0 group-hover:opacity-100 transition-opacity flex justify-end gap-1">
                      <button type="button" onClick={() => openEditModal(m)} className="p-1.5 text-slate-400 hover:text-blue-600 hover:bg-blue-50 rounded">✏️</button>
                      <button type="button" onClick={(e) => handleDelete(e, m.id)} className="p-1.5 text-slate-400 hover:text-red-600 hover:bg-red-50 rounded">🗑️</button>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}

        {view === 'CALENDAR' && (
           <div className="grid grid-cols-7 gap-px bg-slate-200 border border-slate-200 rounded-lg overflow-hidden">
             {['일', '월', '화', '수', '목', '금', '토'].map(d => (
               <div key={d} className="bg-slate-50 p-2 text-center text-xs font-bold text-slate-400">{d}</div>
             ))}
             {calendarDates.map((date, i) => {
               const dateStr = date.toISOString().split('T')[0];
               return (
                 <div key={i} className="bg-white min-h-[110px] p-2 relative group/cell border-r border-b border-slate-100">
                   <span className={`text-xs font-bold ${date.getMonth() === today.getMonth() ? 'text-slate-600' : 'text-slate-300'}`}>
                     {date.getDate()}
                   </span>
                   <div className="mt-1 space-y-1">
                     {milestones.map((m) => {
                        const mStart = new Date(m.startDate);
                        const mEnd = new Date(m.endDate);

                        if (date >= mStart && date <= mEnd) {
                          const isStart = dateStr === m.startDate;
                          const isEnd = dateStr === m.endDate;

                          let colorClass = "";
                          if (isStart) {
                            colorClass = "bg-blue-700 text-white border-blue-800 shadow-sm z-10";
                          } else if (isEnd) {
                            colorClass = "bg-rose-600 text-white border-rose-700 shadow-sm z-10";
                          } else {
                            // 중간 기간 색상
                            colorClass = m.status === 'COMPLETED' ? 'bg-green-100 text-green-700' : 
                                         m.status === 'OVERDUE' ? 'bg-red-100 text-red-700' : 'bg-blue-50 text-blue-600';
                          }

                          return (
                            <div 
                              key={m.id} 
                              onClick={() => openEditModal(m)}
                              className={`p-1 text-[9px] font-bold cursor-pointer transition-all truncate border-y border-transparent hover:brightness-95 ${colorClass} ${
                                isStart ? 'rounded-l-md border-l' : ''
                              } ${
                                isEnd ? 'rounded-r-md border-r' : ''
                              }`}
                              title={`${m.title} (${m.startDate} ~ ${m.endDate})`}
                            >
                              {m.title}
                            </div>
                          );
                        }
                        return null;
                     })}
                   </div>
                 </div>
               );
             })}
           </div>
        )}

        {view === 'GANTT' && (
          <div className="relative min-w-[800px]">
            <div className="flex border-b border-slate-200 mb-4 bg-slate-50 rounded-t-lg overflow-hidden border-x border-t">
              <div className="w-1/4 p-3 font-bold text-xs text-slate-500 bg-white border-r border-slate-200">마일스톤 태스크</div>
              <div className="flex-1 flex divide-x divide-slate-200">
                {ganttConfig.units.map((unit, i) => (
                  <div key={i} className="flex-1 text-[10px] font-bold text-slate-400 text-center py-3 bg-slate-50/50">
                    {unit}
                  </div>
                ))}
              </div>
            </div>

            <div className="space-y-6 px-1">
              {milestones.map((m) => {
                const barStyle = calculateGanttStyle(m);
                return (
                  <div key={m.id} className="flex items-center group">
                    <div className="w-1/4 pr-4 cursor-pointer hover:text-blue-600 transition-colors" onClick={() => openEditModal(m)}>
                      <div className="text-sm font-bold truncate text-slate-700">{m.title}</div>
                      <div className="text-[10px] text-slate-400 font-mono tracking-tighter">{m.startDate} ~ {m.endDate}</div>
                    </div>
                    <div className="flex-1 h-10 bg-slate-50 rounded-lg relative overflow-hidden border border-slate-100 cursor-pointer shadow-inner" onClick={() => openEditModal(m)}>
                      {/* 눈금선 */}
                      <div className="absolute inset-0 flex divide-x divide-slate-200/50 pointer-events-none">
                        {ganttConfig.units.map((_, i) => <div key={i} className="flex-1 h-full" />)}
                      </div>

                      <div 
                        className={`absolute top-1 bottom-1 rounded-full flex items-center px-3 text-[10px] text-white font-black transition-all duration-300 shadow-md hover:brightness-110 ${
                          m.status === 'COMPLETED' ? 'bg-green-500' : m.status === 'OVERDUE' ? 'bg-red-500' : 'bg-blue-500'
                        }`}
                        style={barStyle}
                      >
                        <span className="truncate drop-shadow-sm">{m.title}</span>
                      </div>
                    </div>
                  </div>
                );
              })}
              {milestones.length === 0 && (
                <div className="py-20 text-center text-slate-400 border border-dashed border-slate-200 rounded-xl bg-slate-50/30">
                  등록된 마일스톤이 없습니다.
                </div>
              )}
            </div>
          </div>
        )}
      </div>

      {/* Add/Edit Modal */}
      {(showAdd || editingMilestone) && (
        <div className="fixed inset-0 bg-slate-900/50 backdrop-blur-sm flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-2xl shadow-2xl w-full max-w-md animate-scaleIn overflow-hidden">
            <div className="p-6 border-b border-slate-100 bg-slate-50">
              <h3 className="text-lg font-bold">
                {editingMilestone ? '마일스톤 수정' : '새 마일스톤 추가'}
              </h3>
            </div>
            <div className="p-6 space-y-4">
              <div>
                <label className="block text-xs font-bold text-slate-400 uppercase mb-1">제목</label>
                <input 
                  type="text" 
                  value={formTitle} 
                  onChange={e => setFormTitle(e.target.value)}
                  className="w-full p-2.5 border border-slate-200 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none text-sm"
                />
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-xs font-bold text-slate-400 uppercase mb-1">시작일</label>
                  <input 
                    type="date" 
                    value={formStart} 
                    onChange={e => setFormStart(e.target.value)}
                    className="w-full p-2 border border-slate-200 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none text-sm"
                  />
                </div>
                <div>
                  <label className="block text-xs font-bold text-slate-400 uppercase mb-1">종료일</label>
                  <input 
                    type="date" 
                    value={formEnd} 
                    onChange={e => setFormEnd(e.target.value)}
                    className="w-full p-2 border border-slate-200 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none text-sm"
                  />
                </div>
              </div>
              {editingMilestone && (
                <div>
                  <label className="block text-xs font-bold text-slate-400 uppercase mb-1">진행 상태</label>
                  <select 
                    value={formStatus}
                    onChange={e => setFormStatus(e.target.value as any)}
                    className="w-full p-2 border border-slate-200 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none text-sm font-semibold"
                  >
                    <option value="UPCOMING">UPCOMING</option>
                    <option value="COMPLETED">COMPLETED</option>
                    <option value="OVERDUE">OVERDUE</option>
                  </select>
                </div>
              )}
            </div>
            <div className="p-6 bg-slate-50 flex justify-end gap-3">
              <div className="flex-1">
                {editingMilestone && (
                  <button type="button" onClick={(e) => { if(editingMilestone) { handleDelete(e, editingMilestone.id); setEditingMilestone(null); } }} className="px-4 py-2 text-sm text-red-500 hover:text-red-700 font-bold">삭제</button>
                )}
              </div>
              <button type="button" onClick={() => { setShowAdd(false); setEditingMilestone(null); }} className="px-4 py-2 text-sm text-slate-500 hover:text-slate-700">취소</button>
              <button type="button" onClick={editingMilestone ? handleSaveEdit : handleAdd} className="px-6 py-2 bg-blue-600 text-white rounded-lg text-sm font-bold shadow-lg hover:bg-blue-700">{editingMilestone ? '수정하기' : '추가하기'}</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState } from 'react';
import { Project, Milestone, ViewType, ScaleType } from '../types';
import { MilestoneView } from './MilestoneView';
import { generateTemplate } from '../services/geminiService';
import { getStatus1Color } from '../constants';

interface ProjectDetailProps {
  project: Project;
  onUpdate: (updated: Project) => void;
  status1Options: string[];
  status2Options: string[];
}

export const ProjectDetail: React.FC<ProjectDetailProps> = ({ project, onUpdate, status1Options, status2Options }) => {
  const [activeTab, setActiveTab] = useState<'OVERVIEW' | 'MILESTONES' | 'CHARTER' | 'REPORT' | 'RETRO'>('OVERVIEW');
  const [isGenerating, setIsGenerating] = useState(false);

  // States for editing project info
  const [isEditingHeader, setIsEditingHeader] = useState(false);
  const [editedName, setEditedName] = useState(project.name);
  const [editedDescription, setEditedDescription] = useState(project.description);
  const [editedManager, setEditedManager] = useState(project.manager);
  const [editedStartDate, setEditedStartDate] = useState(project.startDate);
  const [editedEndDate, setEditedEndDate] = useState(project.endDate);

  const handleStatusChange = (field: 'status1' | 'status2', val: string) => {
    onUpdate({ ...project, [field]: val });
  };

  const handleSaveHeader = () => {
    onUpdate({
      ...project,
      name: editedName,
      description: editedDescription,
      manager: editedManager,
      startDate: editedStartDate,
      endDate: editedEndDate
    });
    setIsEditingHeader(false);
  };

  const handleCancelHeader = () => {
    setEditedName(project.name);
    setEditedDescription(project.description);
    setEditedManager(project.manager);
    setEditedStartDate(project.startDate);
    setEditedEndDate(project.endDate);
    setIsEditingHeader(false);
  };

  const handleAutoGenerate = async (type: any) => {
    setIsGenerating(true);
    const content = await generateTemplate(type, {
      name: project.name,
      description: project.description,
      status: `${project.status1} / ${project.status2}`
    });

    const fieldMap: any = {
      CHARTER: 'charter',
      REQUIREMENTS: 'requirements',
      RETROSPECTIVE: 'retrospective'
    };

    if (type === 'WEEKLY_REPORT') {
      const newReport = { id: Date.now().toString(), date: new Date().toISOString().split('T')[0], content };
      onUpdate({ ...project, weeklyReports: [newReport, ...project.weeklyReports] });
    } else {
      onUpdate({ ...project, [fieldMap[type]]: content });
    }
    setIsGenerating(false);
  };

  return (
    <div className="space-y-6 animate-fadeIn">
      {/* Header */}
      <div className="flex flex-col md:flex-row justify-between items-start bg-white p-6 rounded-xl border border-slate-200 shadow-sm gap-6 relative group/header">
        <div className="flex-1 w-full">
          {!isEditingHeader ? (
            <>
              <div className="flex items-center gap-3 mb-2">
                <h2 className="text-2xl font-bold text-slate-900">{project.name}</h2>
                <div className={`px-3 py-1 rounded-full text-[10px] font-black uppercase border ${getStatus1Color(project.status1)}`}>
                  {project.status1}
                </div>
                <button 
                  onClick={() => setIsEditingHeader(true)}
                  className="opacity-0 group-hover/header:opacity-100 transition-opacity p-1 hover:bg-slate-100 rounded text-slate-400"
                  title="정보 수정"
                >
                  <span className="text-xs">✏️</span>
                </button>
              </div>
              <p className="text-slate-500 text-sm max-w-2xl">{project.description}</p>
            </>
          ) : (
            <div className="space-y-3 animate-slideDown">
              <div>
                <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-1 block">프로젝트 이름</label>
                <input 
                  type="text" 
                  value={editedName}
                  onChange={(e) => setEditedName(e.target.value)}
                  className="w-full p-2 text-lg font-bold border border-blue-200 rounded-lg bg-blue-50/30 focus:ring-2 focus:ring-blue-500 outline-none"
                  autoFocus
                />
              </div>
              <div>
                <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-1 block">프로젝트 설명</label>
                <textarea 
                  value={editedDescription}
                  onChange={(e) => setEditedDescription(e.target.value)}
                  className="w-full p-2 text-sm border border-blue-200 rounded-lg bg-blue-50/30 focus:ring-2 focus:ring-blue-500 outline-none h-20 resize-none"
                />
              </div>
            </div>
          )}
        </div>

        <div className="flex flex-wrap gap-4 min-w-[320px] pt-2 md:pt-0">
          <div className="flex-1 flex flex-col gap-1.5">
            <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">대분류 상태 (1depth)</label>
            <select 
              value={project.status1} 
              onChange={(e) => handleStatusChange('status1', e.target.value)}
              className="w-full p-2.5 text-sm border border-slate-200 rounded-lg bg-slate-50 focus:ring-2 focus:ring-blue-500 outline-none font-semibold transition-all cursor-pointer"
            >
              {status1Options.map(opt => <option key={opt} value={opt}>{opt}</option>)}
            </select>
          </div>
          <div className="flex-1 flex flex-col gap-1.5">
            <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">상세 프로세스 (2depth)</label>
            <select 
              value={project.status2} 
              onChange={(e) => handleStatusChange('status2', e.target.value)}
              className="w-full p-2.5 text-sm border border-slate-200 rounded-lg bg-slate-50 focus:ring-2 focus:ring-blue-500 outline-none font-semibold transition-all cursor-pointer"
            >
              {status2Options.map(opt => <option key={opt} value={opt}>{opt}</option>)}
            </select>
          </div>
        </div>
      </div>

      {/* Tabs */}
      <div className="flex border-b border-slate-200 overflow-x-auto bg-white/50 backdrop-blur-sm sticky top-0 z-10">
        {[
          { id: 'OVERVIEW', label: '개요', icon: '📝' },
          { id: 'MILESTONES', label: '마일스톤', icon: '📅' },
          { id: 'CHARTER', label: 'Project Charter', icon: '📜' },
          { id: 'REPORT', label: '주간 보고', icon: '📊' },
          { id: 'RETRO', label: '회고', icon: '💡' },
        ].map(tab => (
          <button
            key={tab.id}
            onClick={() => setActiveTab(tab.id as any)}
            className={`px-6 py-3 text-sm font-medium border-b-2 transition-colors flex items-center gap-2 whitespace-nowrap ${
              activeTab === tab.id ? 'border-blue-600 text-blue-600' : 'border-transparent text-slate-400 hover:text-slate-600'
            }`}
          >
            <span>{tab.icon}</span> {tab.label}
          </button>
        ))}
      </div>

      {/* Content Area */}
      <div className="min-h-[500px]">
        {activeTab === 'OVERVIEW' && (
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
            <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm">
              <h3 className="font-semibold mb-4 flex justify-between items-center text-slate-800">
                상세 정보 및 요구사항
                <button 
                  onClick={() => handleAutoGenerate('REQUIREMENTS')}
                  className="text-xs text-blue-600 hover:underline font-bold bg-blue-50 px-2 py-1 rounded"
                  disabled={isGenerating}
                >
                  {isGenerating ? '생성 중...' : '✨ AI로 요구사항 생성'}
                </button>
              </h3>
              <div className="prose prose-sm max-w-none text-slate-600">
                {project.requirements ? (
                  <div className="whitespace-pre-wrap bg-slate-50 p-4 rounded-lg border border-slate-100 leading-relaxed">{project.requirements}</div>
                ) : (
                  <div className="p-8 text-center bg-slate-50 rounded-lg border border-dashed border-slate-200">
                    <p className="italic text-slate-400 mb-2 text-xs">요구사항 내용이 없습니다.</p>
