import React, { useState, useMemo } from 'react';
import { Milestone, ViewType, ScaleType } from '../types';

interface MilestoneViewProps {
  milestones: Milestone[];
  onUpdateMilestones: (milestones: Milestone[]) => void;
}

export const MilestoneView: React.FC<MilestoneViewProps> = ({ milestones, onUpdateMilestones }) => {
  const [view, setView] = useState<ViewType>('LIST');
  const [scale, setScale] = useState<ScaleType>('MONTH');

  // Calendar Navigation State
  const [viewDate, setViewDate] = useState(new Date());

  // Modals state
  const [showAdd, setShowAdd] = useState(false);
  const [editingMilestone, setEditingMilestone] = useState<Milestone | null>(null);

  // Form states
  const [formTitle, setFormTitle] = useState('');
  const [formStart, setFormStart] = useState('');
  const [formEnd, setFormEnd] = useState('');
  const [formStatus, setFormStatus] = useState<Milestone['status']>('UPCOMING');

  const openAddModal = () => {
    setFormTitle('');
    setFormStart('');
    setFormEnd('');
    setFormStatus('UPCOMING');
    setShowAdd(true);
  };

  const openEditModal = (m: Milestone) => {
    setEditingMilestone(m);
    setFormTitle(m.title);
    setFormStart(m.startDate);
    setFormEnd(m.endDate);
    setFormStatus(m.status);
  };

  const handleAdd = () => {
    if (!formTitle || !formStart || !formEnd) return;
    const newMilestone: Milestone = {
      id: Math.random().toString(36).substr(2, 9),
      title: formTitle,
      startDate: formStart,
      endDate: formEnd,
      status: 'UPCOMING'
    };
    onUpdateMilestones([...milestones, newMilestone]);
    setShowAdd(false);
  };

  const handleSaveEdit = () => {
    if (!editingMilestone || !formTitle || !formStart || !formEnd) return;
    const updatedList = milestones.map(m => 
      m.id === editingMilestone.id 
        ? { ...m, title: formTitle, startDate: formStart, endDate: formEnd, status: formStatus }
        : m
    );
    onUpdateMilestones(updatedList);
    setEditingMilestone(null);
  };

  const handleDelete = (e: React.MouseEvent, id: string) => {
    e.preventDefault();
    e.stopPropagation();
    if (window.confirm('이 마일스톤을 정말 삭제하시겠습니까?')) {
      const filtered = milestones.filter(m => m.id !== id);
      onUpdateMilestones(filtered);
    }
  };

  // --- Navigation Helpers ---
  const handlePrevMonth = () => {
    setViewDate(new Date(viewDate.getFullYear(), viewDate.getMonth() - 1, 1));
  };
  const handleNextMonth = () => {
    setViewDate(new Date(viewDate.getFullYear(), viewDate.getMonth() + 1, 1));
  };
  const handleToday = () => setViewDate(new Date());

  // --- Date Helpers ---
  const today = new Date();
  today.setHours(0, 0, 0, 0);

  // Calendar 날짜 배열 생성 (실제 달력처럼 요일 정렬)
  const calendarDates = useMemo(() => {
    const startOfMonth = new Date(viewDate.getFullYear(), viewDate.getMonth(), 1);
    const startDay = startOfMonth.getDay(); // 0 (Sun) to 6 (Sat)

    // 달력의 첫 번째 칸에 해당하는 날짜 (이전 달의 일부 날짜 포함 가능)
    const startDate = new Date(startOfMonth);
    startDate.setDate(startDate.getDate() - startDay);

    const dates = [];
    // 6주치 데이터 (42일)
    for (let i = 0; i < 42; i++) {
      const d = new Date(startDate);
      d.setDate(startDate.getDate() + i);
      dates.push(d);
    }
    return dates;
  }, [viewDate]);

  // Gantt 타임라인 데이터 및 범위 계산
  const ganttConfig = useMemo(() => {
    const units = [];
    let startRange = new Date(today);
    let endRange = new Date(today);

    if (scale === 'DAY') {
      startRange = new Date(today);
      for (let i = 0; i < 10; i++) {
        const d = new Date(today);
        d.setDate(today.getDate() + i);
        units.push(`${d.getMonth() + 1}/${d.getDate()}`);
      }
      endRange.setDate(today.getDate() + 10);
    } else if (scale === 'MONTH') {
      startRange = new Date(today.getFullYear(), 0, 1);
      for (let i = 1; i <= 12; i++) units.push(`${i}월`);
      endRange = new Date(today.getFullYear(), 11, 31);
    } else if (scale === 'QUARTER') {
      startRange = new Date(today.getFullYear(), 0, 1);
      for (let i = 1; i <= 4; i++) units.push(`${i}분기`);
      endRange = new Date(today.getFullYear(), 11, 31);
    } else if (scale === 'YEAR') {
      const startYear = today.getFullYear() - 1;
      startRange = new Date(startYear, 0, 1);
      for (let i = 0; i < 4; i++) units.push(`${startYear + i}년`);
      endRange = new Date(startYear + 3, 11, 31);
    }

    return { units, startRange, endRange };
  }, [scale, today]);

  // Gantt 바 위치/너비 계산 함수
  const calculateGanttStyle = (m: Milestone) => {
    const { startRange, endRange } = ganttConfig;
    const mStart = new Date(m.startDate);
    const mEnd = new Date(m.endDate);

    const totalDuration = endRange.getTime() - startRange.getTime();

    // 시작 위치 (%)
    let left = ((mStart.getTime() - startRange.getTime()) / totalDuration) * 100;
    // 너비 (%)
    let width = ((mEnd.getTime() - mStart.getTime()) / totalDuration) * 100;

    // 범위 보정 (타임라인 밖으로 나가는 경우 처리)
    if (left < 0) {
      width = width + left;
      left = 0;
    }
    if (left + width > 100) {
      width = 100 - left;
    }
    if (width < 0) return { display: 'none' };

    return { left: `${left}%`, width: `${width}%` };
  };

  return (
    <div className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden">
      <div className="p-4 border-b border-slate-100 flex flex-wrap justify-between items-center gap-4 bg-slate-50/50">
        <div className="flex gap-2 p-1 bg-slate-200/50 rounded-lg">
          {(['LIST', 'CALENDAR', 'GANTT'] as ViewType[]).map(v => (
            <button
              key={v}
              onClick={() => setView(v)}
              className={`px-4 py-1.5 text-xs font-bold rounded-md transition-all ${
                view === v ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500 hover:text-slate-800'
              }`}
            >
              {v}
            </button>
          ))}
        </div>

        {view === 'GANTT' && (
          <div className="flex gap-1">
            {(['DAY', 'MONTH', 'QUARTER', 'YEAR'] as ScaleType[]).map(s => (
              <button
                key={s}
                onClick={() => setScale(s)}
                className={`px-3 py-1 text-[10px] rounded border ${
                  scale === s ? 'bg-slate-900 text-white border-slate-900' : 'bg-white text-slate-500 border-slate-200 hover:bg-slate-50'
                }`}
              >
                {s}
              </button>
            ))}
          </div>
        )}

        {view === 'CALENDAR' && (
          <div className="flex items-center gap-3">
            <button onClick={handlePrevMonth} className="p-1 hover:bg-slate-200 rounded text-slate-500">◀</button>
            <div className="text-sm font-bold text-slate-700 min-w-[100px] text-center">
              {viewDate.getFullYear()}년 {viewDate.getMonth() + 1}월
            </div>
            <button onClick={handleNextMonth} className="p-1 hover:bg-slate-200 rounded text-slate-500">▶</button>
            <button onClick={handleToday} className="px-2 py-1 text-[10px] font-bold bg-slate-100 text-slate-600 rounded hover:bg-slate-200">오늘</button>
          </div>
        )}

        <button 
          onClick={openAddModal}
          className="px-4 py-1.5 bg-blue-600 text-white text-xs font-bold rounded-lg hover:bg-blue-700 flex items-center gap-2 shadow-sm"
        >
          <span>+</span> 마일스톤 추가
        </button>
      </div>

      <div className="p-6 overflow-x-auto min-h-[400px]">
        {view === 'LIST' && (
          <table className="w-full text-left">
            <thead>
              <tr className="text-xs text-slate-400 uppercase tracking-wider">
                <th className="pb-4 font-semibold px-2">마일스톤명</th>
                <th className="pb-4 font-semibold px-2 text-center">기간</th>
                <th className="pb-4 font-semibold px-2 text-center">상태</th>
                <th className="pb-4 font-semibold px-2 text-right">관리</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {milestones.map(m => (
                <tr key={m.id} className="text-sm group hover:bg-slate-50/50 transition-colors">
                  <td className="py-4 font-bold text-slate-700 px-2 cursor-pointer" onClick={() => openEditModal(m)}>{m.title}</td>
                  <td className="py-4 text-slate-500 px-2 text-center text-xs font-mono cursor-pointer" onClick={() => openEditModal(m)}>
                    {m.startDate} ~ {m.endDate}
                  </td>
                  <td className="py-4 px-2 text-center">
                    <span className={`px-2 py-0.5 rounded-full text-[10px] font-bold ${
                      m.status === 'COMPLETED' ? 'bg-green-100 text-green-700' : 
                      m.status === 'OVERDUE' ? 'bg-red-100 text-red-700' : 'bg-blue-100 text-blue-700'
                    }`}>
                      {m.status}
                    </span>
                  </td>
                  <td className="py-4 px-2 text-right space-x-1">
                    <div className="opacity-0 group-hover:opacity-100 transition-opacity flex justify-end gap-1">
                      <button type="button" onClick={() => openEditModal(m)} className="p-1.5 text-slate-400 hover:text-blue-600 hover:bg-blue-50 rounded">✏️</button>
                      <button type="button" onClick={(e) => handleDelete(e, m.id)} className="p-1.5 text-slate-400 hover:text-red-600 hover:bg-red-50 rounded">🗑️</button>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}

        {view === 'CALENDAR' && (
           <div className="grid grid-cols-7 gap-px bg-slate-200 border border-slate-200 rounded-lg overflow-hidden">
             {['일', '월', '화', '수', '목', '금', '토'].map(d => (
               <div key={d} className="bg-slate-50 p-2 text-center text-xs font-bold text-slate-400">{d}</div>
             ))}
             {calendarDates.map((date, i) => {
               const dateStr = date.toISOString().split('T')[0];
               const isSameMonth = date.getMonth() === viewDate.getMonth();
               const isToday = date.getTime() === today.getTime();

               return (
                 <div key={i} className={`bg-white min-h-[110px] p-2 relative group/cell border-r border-b border-slate-100 ${!isSameMonth ? 'bg-slate-50/50' : ''}`}>
                   <span className={`text-xs font-bold px-1.5 py-0.5 rounded-full ${
                     isToday ? 'bg-blue-600 text-white' : 
                     isSameMonth ? 'text-slate-600' : 'text-slate-300'
                   }`}>
                     {date.getDate()}
                   </span>
                   <div className="mt-1 space-y-1">
                     {milestones.map((m) => {
                        const mStart = new Date(m.startDate);
                        const mEnd = new Date(m.endDate);
                        mStart.setHours(0,0,0,0);
                        mEnd.setHours(0,0,0,0);

                        if (date >= mStart && date <= mEnd) {
                          const isStart = dateStr === m.startDate;
                          const isEnd = dateStr === m.endDate;

                          let colorClass = "";
                          if (isStart) {
                            colorClass = "bg-blue-700 text-white border-blue-800 shadow-sm z-10";
                          } else if (isEnd) {
                            colorClass = "bg-rose-600 text-white border-rose-700 shadow-sm z-10";
                          } else {
                            colorClass = m.status === 'COMPLETED' ? 'bg-green-100 text-green-700' : 
                                         m.status === 'OVERDUE' ? 'bg-red-100 text-red-700' : 'bg-blue-50 text-blue-600';
                          }

                          return (
                            <div 
                              key={m.id} 
                              onClick={() => openEditModal(m)}
                              className={`p-1 text-[9px] font-bold cursor-pointer transition-all truncate border-y border-transparent hover:brightness-95 ${colorClass} ${
                                isStart ? 'rounded-l-md border-l' : ''
                              } ${
                                isEnd ? 'rounded-r-md border-r' : ''
                              }`}
                              title={`${m.title} (${m.startDate} ~ ${m.endDate})`}
                            >
                              {m.title}
                            </div>
                          );
                        }
                        return null;
                     })}
                   </div>
                 </div>
               );
             })}
           </div>
        )}

        {view === 'GANTT' && (
          <div className="relative min-w-[800px]">
            <div className="flex border-b border-slate-200 mb-4 bg-slate-50 rounded-t-lg overflow-hidden border-x border-t">
              <div className="w-1/4 p-3 font-bold text-xs text-slate-500 bg-white border-r border-slate-200">마일스톤 태스크</div>
              <div className="flex-1 flex divide-x divide-slate-200">
                {ganttConfig.units.map((unit, i) => (
                  <div key={i} className="flex-1 text-[10px] font-bold text-slate-400 text-center py-3 bg-slate-50/50">
                    {unit}
                  </div>
                ))}
              </div>
            </div>

            <div className="space-y-6 px-1">
              {milestones.map((m) => {
                const barStyle = calculateGanttStyle(m);
                return (
                  <div key={m.id} className="flex items-center group">
                    <div className="w-1/4 pr-4 cursor-pointer hover:text-blue-600 transition-colors" onClick={() => openEditModal(m)}>
                      <div className="text-sm font-bold truncate text-slate-700">{m.title}</div>
                      <div className="text-[10px] text-slate-400 font-mono tracking-tighter">{m.startDate} ~ {m.endDate}</div>
                    </div>
                    <div className="flex-1 h-10 bg-slate-50 rounded-lg relative overflow-hidden border border-slate-100 cursor-pointer shadow-inner" onClick={() => openEditModal(m)}>
                      {/* 눈금선 */}
                      <div className="absolute inset-0 flex divide-x divide-slate-200/50 pointer-events-none">
                        {ganttConfig.units.map((_, i) => <div key={i} className="flex-1 h-full" />)}
                      </div>

                      <div 
                        className={`absolute top-1 bottom-1 rounded-full flex items-center px-3 text-[10px] text-white font-black transition-all duration-300 shadow-md hover:brightness-110 ${
                          m.status === 'COMPLETED' ? 'bg-green-500' : m.status === 'OVERDUE' ? 'bg-red-500' : 'bg-blue-500'
                        }`}
                        style={barStyle}
                      >
                        <span className="truncate drop-shadow-sm">{m.title}</span>
                      </div>
                    </div>
                  </div>
                );
              })}
              {milestones.length === 0 && (
                <div className="py-20 text-center text-slate-400 border border-dashed border-slate-200 rounded-xl bg-slate-50/30">
                  등록된 마일스톤이 없습니다.
                </div>
              )}
            </div>
          </div>
        )}
      </div>

      {/* Add/Edit Modal */}
      {(showAdd || editingMilestone) && (
        <div className="fixed inset-0 bg-slate-900/50 backdrop-blur-sm flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-2xl shadow-2xl w-full max-w-md animate-scaleIn overflow-hidden">
            <div className="p-6 border-b border-slate-100 bg-slate-50">
              <h3 className="text-lg font-bold">
                {editingMilestone ? '마일스톤 수정' : '새 마일스톤 추가'}
              </h3>
            </div>
            <div className="p-6 space-y-4">
              <div>
                <label className="block text-xs font-bold text-slate-400 uppercase mb-1">제목</label>
                <input 
                  type="text" 
                  value={formTitle} 
                  onChange={e => setFormTitle(e.target.value)}
                  className="w-full p-2.5 border border-slate-200 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none text-sm"
                />
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-xs font-bold text-slate-400 uppercase mb-1">시작일</label>
                  <input 
                    type="date" 
                    value={formStart} 
                    onChange={e => setFormStart(e.target.value)}
                    className="w-full p-2 border border-slate-200 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none text-sm"
                  />
                </div>
                <div>
                  <label className="block text-xs font-bold text-slate-400 uppercase mb-1">종료일</label>
                  <input 
                    type="date" 
                    value={formEnd} 
                    onChange={e => setFormEnd(e.target.value)}
                    className="w-full p-2 border border-slate-200 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none text-sm"
                  />
                </div>
              </div>
              {editingMilestone && (
                <div>
                  <label className="block text-xs font-bold text-slate-400 uppercase mb-1">진행 상태</label>
                  <select 
                    value={formStatus}
                    onChange={e => setFormStatus(e.target.value as any)}
                    className="w-full p-2 border border-slate-200 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none text-sm font-semibold"
                  >
                    <option value="UPCOMING">UPCOMING</option>
                    <option value="COMPLETED">COMPLETED</option>
                    <option value="OVERDUE">OVERDUE</option>
                  </select>
                </div>
              )}
            </div>
            <div className="p-6 bg-slate-50 flex justify-end gap-3">
              <div className="flex-1">
                {editingMilestone && (
                  <button type="button" onClick={(e) => { if(editingMilestone) { handleDelete(e, editingMilestone.id); setEditingMilestone(null); } }} className="px-4 py-2 text-sm text-red-500 hover:text-red-700 font-bold">삭제</button>
                )}
              </div>
              <button type="button" onClick={() => { setShowAdd(false); setEditingMilestone(null); }} className="px-4 py-2 text-sm text-slate-500 hover:text-slate-700">취소</button>
              <button type="button" onClick={editingMilestone ? handleSaveEdit : handleAdd} className="px-6 py-2 bg-blue-600 text-white rounded-lg text-sm font-bold shadow-lg hover:bg-blue-700">{editingMilestone ? '수정하기' : '추가하기'}</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { Milestone, ViewType, ScaleType } from '../types';

interface MilestoneViewProps {
  milestones: Milestone[];
  onUpdateMilestones: (milestones: Milestone[]) => void;
}

export const MilestoneView: React.FC<MilestoneViewProps> = ({ milestones, onUpdateMilestones }) => {
  const [view, setView] = useState<ViewType>('LIST');
  const [scale, setScale] = useState<ScaleType>('MONTH');

  // Calendar Navigation State
  const [viewDate, setViewDate] = useState(new Date());

  // Gantt Navigation State
  const [ganttBaseDate, setGanttBaseDate] = useState(new Date());

  // Modals state
  const [showAdd, setShowAdd] = useState(false);
  const [editingMilestone, setEditingMilestone] = useState<Milestone | null>(null);

  // Form states
  const [formTitle, setFormTitle] = useState('');
  const [formStart, setFormStart] = useState('');
  const [formEnd, setFormEnd] = useState('');
  const [formStatus, setFormStatus] = useState<Milestone['status']>('UPCOMING');

  const openAddModal = () => {
    setFormTitle('');
    setFormStart('');
    setFormEnd('');
    setFormStatus('UPCOMING');
    setShowAdd(true);
  };

  const openEditModal = (m: Milestone) => {
    setEditingMilestone(m);
    setFormTitle(m.title);
    setFormStart(m.startDate);
    setFormEnd(m.endDate);
    setFormStatus(m.status);
  };

  const handleAdd = () => {
    if (!formTitle || !formStart || !formEnd) return;
    const newMilestone: Milestone = {
      id: Math.random().toString(36).substr(2, 9),
      title: formTitle,
      startDate: formStart,
      endDate: formEnd,
      status: 'UPCOMING'
    };
    onUpdateMilestones([...milestones, newMilestone]);
    setShowAdd(false);
  };

  const handleSaveEdit = () => {
    if (!editingMilestone || !formTitle || !formStart || !formEnd) return;
    const updatedList = milestones.map(m => 
      m.id === editingMilestone.id 
        ? { ...m, title: formTitle, startDate: formStart, endDate: formEnd, status: formStatus }
        : m
    );
    onUpdateMilestones(updatedList);
    setEditingMilestone(null);
  };

  const handleDelete = (e: React.MouseEvent, id: string) => {
    e.preventDefault();
    e.stopPropagation();
    if (window.confirm('이 마일스톤을 정말 삭제하시겠습니까?')) {
      const filtered = milestones.filter(m => m.id !== id);
      onUpdateMilestones(filtered);
    }
  };

  // --- Navigation Helpers (Calendar) ---
  const handlePrevMonth = () => {
    setViewDate(new Date(viewDate.getFullYear(), viewDate.getMonth() - 1, 1));
  };
  const handleNextMonth = () => {
    setViewDate(new Date(viewDate.getFullYear(), viewDate.getMonth() + 1, 1));
  };
  const handleToday = () => {
    const d = new Date();
    setViewDate(d);
    setGanttBaseDate(d);
  };

  // --- Navigation Helpers (Gantt) ---
  const handleGanttPrev = () => {
    const d = new Date(ganttBaseDate);
    if (scale === 'DAY') d.setDate(d.getDate() - 7);
    else if (scale === 'MONTH' || scale === 'QUARTER') d.setFullYear(d.getFullYear() - 1);
    else if (scale === 'YEAR') d.setFullYear(d.getFullYear() - 5);
    setGanttBaseDate(d);
  };

  const handleGanttNext = () => {
    const d = new Date(ganttBaseDate);
    if (scale === 'DAY') d.setDate(d.getDate() + 7);
    else if (scale === 'MONTH' || scale === 'QUARTER') d.setFullYear(d.getFullYear() + 1);
    else if (scale === 'YEAR') d.setFullYear(d.getFullYear() + 5);
    setGanttBaseDate(d);
  };

  // --- Zoom logic (Mouse Wheel) ---
  const scales: ScaleType[] = ['DAY', 'MONTH', 'QUARTER', 'YEAR'];
  const handleGanttWheel = (e: React.WheelEvent) => {
    const currentIndex = scales.indexOf(scale);
    if (e.deltaY < 0) { // Scroll Up: Zoom In (closer view)
      if (currentIndex > 0) setScale(scales[currentIndex - 1]);
    } else { // Scroll Down: Zoom Out (wider view)
      if (currentIndex < scales.length - 1) setScale(scales[currentIndex + 1]);
    }
  };

  // --- Date Helpers ---
  const today = new Date();
  today.setHours(0, 0, 0, 0);

  // Calendar 날짜 배열 생성
  const calendarDates = useMemo(() => {
    const startOfMonth = new Date(viewDate.getFullYear(), viewDate.getMonth(), 1);
    const startDay = startOfMonth.getDay();
    const startDate = new Date(startOfMonth);
    startDate.setDate(startDate.getDate() - startDay);
    const dates = [];
    for (let i = 0; i < 42; i++) {
      const d = new Date(startDate);
      d.setDate(startDate.getDate() + i);
      dates.push(d);
    }
    return dates;
  }, [viewDate]);

  // Gantt 타임라인 데이터 및 범위 계산
  const ganttConfig = useMemo(() => {
    const units = [];
    let startRange: Date;
    let endRange: Date;
    let label = "";

    if (scale === 'DAY') {
      // Show 14 days from base date
      startRange = new Date(ganttBaseDate);
      startRange.setHours(0,0,0,0);
      for (let i = 0; i < 14; i++) {
        const d = new Date(startRange);
        d.setDate(startRange.getDate() + i);
        units.push(`${d.getMonth() + 1}/${d.getDate()}`);
      }
      endRange = new Date(startRange);
      endRange.setDate(startRange.getDate() + 14);
      label = `${startRange.getFullYear()}년 ${startRange.getMonth() + 1}월 ${startRange.getDate()}일 기준 (2주)`;
    } else if (scale === 'MONTH') {
      // Show 12 months for the year
      const year = ganttBaseDate.getFullYear();
      startRange = new Date(year, 0, 1);
      for (let i = 1; i <= 12; i++) units.push(`${i}월`);
      endRange = new Date(year, 11, 31, 23, 59, 59);
      label = `${year}년 (전체 월)`;
    } else if (scale === 'QUARTER') {
      const year = ganttBaseDate.getFullYear();
      startRange = new Date(year, 0, 1);
      for (let i = 1; i <= 4; i++) units.push(`${i}분기`);
      endRange = new Date(year, 11, 31, 23, 59, 59);
      label = `${year}년 (분기별)`;
    } else { // YEAR
      // Show 5 years range
      const midYear = ganttBaseDate.getFullYear();
      startRange = new Date(midYear - 2, 0, 1);
      for (let i = 0; i < 5; i++) units.push(`${midYear - 2 + i}년`);
      endRange = new Date(midYear + 2, 11, 31, 23, 59, 59);
      label = `${midYear - 2}년 ~ ${midYear + 2}년`;
    }

    return { units, startRange, endRange, label };
  }, [scale, ganttBaseDate]);

  // Gantt 바 위치/너비 계산 함수
  const calculateGanttStyle = (m: Milestone) => {
    const { startRange, endRange } = ganttConfig;
    const mStart = new Date(m.startDate);
    const mEnd = new Date(m.endDate);

    const totalDuration = endRange.getTime() - startRange.getTime();

    let left = ((mStart.getTime() - startRange.getTime()) / totalDuration) * 100;
    let width = ((mEnd.getTime() - mStart.getTime()) / totalDuration) * 100;

    // Visibility clipping
    if (left + width < 0 || left > 100) return { display: 'none' };

    if (left < 0) {
      width = width + left;
      left = 0;
    }
    if (left + width > 100) {
      width = 100 - left;
    }
    if (width < 0.5) width = 0.5; // 최소 가시성 확보

    return { left: `${left}%`, width: `${width}%` };
  };

  return (
    <div className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden">
      <div className="p-4 border-b border-slate-100 flex flex-wrap justify-between items-center gap-4 bg-slate-50/50">
        <div className="flex gap-2 p-1 bg-slate-200/50 rounded-lg">
          {(['LIST', 'CALENDAR', 'GANTT'] as ViewType[]).map(v => (
            <button
              key={v}
              onClick={() => setView(v)}
              className={`px-4 py-1.5 text-xs font-bold rounded-md transition-all ${
                view === v ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500 hover:text-slate-800'
              }`}
            >
              {v}
            </button>
          ))}
        </div>

        {view === 'GANTT' && (
          <div className="flex items-center gap-4">
            <div className="flex bg-slate-100 p-1 rounded-lg">
              {(['DAY', 'MONTH', 'QUARTER', 'YEAR'] as ScaleType[]).map(s => (
                <button
                  key={s}
                  onClick={() => setScale(s)}
                  className={`px-3 py-1 text-[10px] font-bold rounded ${
                    scale === s ? 'bg-white text-slate-900 shadow-sm' : 'text-slate-500 hover:text-slate-800'
                  }`}
                >
                  {s}
                </button>
              ))}
            </div>
            <div className="flex items-center gap-2">
              <button onClick={handleGanttPrev} className="p-1 hover:bg-slate-200 rounded text-slate-500 text-xs">◀</button>
              <span className="text-xs font-bold text-slate-600 min-w-[120px] text-center">{ganttConfig.label}</span>
              <button onClick={handleGanttNext} className="p-1 hover:bg-slate-200 rounded text-slate-500 text-xs">▶</button>
            </div>
          </div>
        )}

        {view === 'CALENDAR' && (
          <div className="flex items-center gap-3">
            <button onClick={handlePrevMonth} className="p-1 hover:bg-slate-200 rounded text-slate-500">◀</button>
            <div className="text-sm font-bold text-slate-700 min-w-[100px] text-center">
              {viewDate.getFullYear()}년 {viewDate.getMonth() + 1}월
            </div>
            <button onClick={handleNextMonth} className="p-1 hover:bg-slate-200 rounded text-slate-500">▶</button>
            <button onClick={handleToday} className="px-2 py-1 text-[10px] font-bold bg-slate-100 text-slate-600 rounded hover:bg-slate-200">오늘</button>
          </div>
        )}

        {view === 'LIST' && <div className="flex-1" />}

        <button 
          onClick={openAddModal}
          className="px-4 py-1.5 bg-blue-600 text-white text-xs font-bold rounded-lg hover:bg-blue-700 flex items-center gap-2 shadow-sm"
        >
          <span>+</span> 마일스톤 추가
        </button>
      </div>

      <div className="p-6 overflow-x-auto min-h-[400px]">
        {view === 'LIST' && (
          <table className="w-full text-left">
            <thead>
              <tr className="text-xs text-slate-400 uppercase tracking-wider">
                <th className="pb-4 font-semibold px-2">마일스톤명</th>
                <th className="pb-4 font-semibold px-2 text-center">기간</th>
                <th className="pb-4 font-semibold px-2 text-center">상태</th>
                <th className="pb-4 font-semibold px-2 text-right">관리</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {milestones.map(m => (
                <tr key={m.id} className="text-sm group hover:bg-slate-50/50 transition-colors">
                  <td className="py-4 font-bold text-slate-700 px-2 cursor-pointer" onClick={() => openEditModal(m)}>{m.title}</td>
                  <td className="py-4 text-slate-500 px-2 text-center text-xs font-mono cursor-pointer" onClick={() => openEditModal(m)}>
                    {m.startDate} ~ {m.endDate}
                  </td>
                  <td className="py-4 px-2 text-center">
                    <span className={`px-2 py-0.5 rounded-full text-[10px] font-bold ${
                      m.status === 'COMPLETED' ? 'bg-green-100 text-green-700' : 
                      m.status === 'OVERDUE' ? 'bg-red-100 text-red-700' : 'bg-blue-100 text-blue-700'
                    }`}>
                      {m.status}
                    </span>
                  </td>
                  <td className="py-4 px-2 text-right space-x-1">
                    <div className="opacity-0 group-hover:opacity-100 transition-opacity flex justify-end gap-1">
                      <button type="button" onClick={() => openEditModal(m)} className="p-1.5 text-slate-400 hover:text-blue-600 hover:bg-blue-50 rounded">✏️</button>
                      <button type="button" onClick={(e) => handleDelete(e, m.id)} className="p-1.5 text-slate-400 hover:text-red-600 hover:bg-red-50 rounded">🗑️</button>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}

        {view === 'CALENDAR' && (
           <div className="grid grid-cols-7 gap-px bg-slate-200 border border-slate-200 rounded-lg overflow-hidden">
             {['일', '월', '화', '수', '목', '금', '토'].map(d => (
               <div key={d} className="bg-slate-50 p-2 text-center text-xs font-bold text-slate-400">{d}</div>
             ))}
             {calendarDates.map((date, i) => {
               const dateStr = date.toISOString().split('T')[0];
               const isSameMonth = date.getMonth() === viewDate.getMonth();
               const isToday = date.getTime() === today.getTime();

               return (
                 <div key={i} className={`bg-white min-h-[110px] p-2 relative group/cell border-r border-b border-slate-100 ${!isSameMonth ? 'bg-slate-50/50' : ''}`}>
                   <span className={`text-xs font-bold px-1.5 py-0.5 rounded-full ${
                     isToday ? 'bg-blue-600 text-white' : 
                     isSameMonth ? 'text-slate-600' : 'text-slate-300'
                   }`}>
                     {date.getDate()}
                   </span>
                   <div className="mt-1 space-y-1">
                     {milestones.map((m) => {
                        const mStart = new Date(m.startDate);
                        const mEnd = new Date(m.endDate);
                        mStart.setHours(0,0,0,0);
                        mEnd.setHours(0,0,0,0);

                        if (date >= mStart && date <= mEnd) {
                          const isStart = dateStr === m.startDate;
                          const isEnd = dateStr === m.endDate;

                          let colorClass = "";
                          if (isStart) {
                            colorClass = "bg-blue-700 text-white border-blue-800 shadow-sm z-10";
                          } else if (isEnd) {
                            colorClass = "bg-rose-600 text-white border-rose-700 shadow-sm z-10";
                          } else {
                            colorClass = m.status === 'COMPLETED' ? 'bg-green-100 text-green-700' : 
                                         m.status === 'OVERDUE' ? 'bg-red-100 text-red-700' : 'bg-blue-50 text-blue-600';
                          }

                          return (
                            <div 
                              key={m.id} 
                              onClick={() => openEditModal(m)}
                              className={`p-1 text-[9px] font-bold cursor-pointer transition-all truncate border-y border-transparent hover:brightness-95 ${colorClass} ${
                                isStart ? 'rounded-l-md border-l' : ''
                              } ${
                                isEnd ? 'rounded-r-md border-r' : ''
                              }`}
                              title={`${m.title} (${m.startDate} ~ ${m.endDate})`}
                            >
                              {m.title}
                            </div>
                          );
                        }
                        return null;
                     })}
                   </div>
                 </div>
               );
             })}
           </div>
        )}

        {view === 'GANTT' && (
          <div 
            className="relative min-w-[800px] select-none"
            onWheel={handleGanttWheel}
          >
            <div className="flex border-b border-slate-200 mb-4 bg-slate-50 rounded-t-lg overflow-hidden border-x border-t">
              <div className="w-1/4 p-3 font-bold text-xs text-slate-500 bg-white border-r border-slate-200">마일스톤 태스크</div>
              <div className="flex-1 flex divide-x divide-slate-200">
                {ganttConfig.units.map((unit, i) => (
                  <div key={i} className="flex-1 text-[10px] font-bold text-slate-400 text-center py-3 bg-slate-50/50">
                    {unit}
                  </div>
                ))}
              </div>
            </div>

            <div className="space-y-6 px-1">
              {milestones.map((m) => {
                const barStyle = calculateGanttStyle(m);
                return (
                  <div key={m.id} className="flex items-center group">
                    <div className="w-1/4 pr-4 cursor-pointer hover:text-blue-600 transition-colors" onClick={() => openEditModal(m)}>
                      <div className="text-sm font-bold truncate text-slate-700">{m.title}</div>
                      <div className="text-[10px] text-slate-400 font-mono tracking-tighter">{m.startDate} ~ {m.endDate}</div>
                    </div>
                    <div className="flex-1 h-10 bg-slate-50 rounded-lg relative overflow-hidden border border-slate-100 cursor-pointer shadow-inner" onClick={() => openEditModal(m)}>
                      {/* 눈금선 */}
                      <div className="absolute inset-0 flex divide-x divide-slate-200/50 pointer-events-none">
                        {ganttConfig.units.map((_, i) => <div key={i} className="flex-1 h-full" />)}
                      </div>

                      <div 
                        className={`absolute top-1 bottom-1 rounded-full flex items-center px-3 text-[10px] text-white font-black transition-all duration-300 shadow-md hover:brightness-110 ${
                          m.status === 'COMPLETED' ? 'bg-green-500' : m.status === 'OVERDUE' ? 'bg-red-500' : 'bg-blue-500'
                        }`}
                        style={barStyle}
                      >
                        <span className="truncate drop-shadow-sm">{m.title}</span>
                      </div>
                    </div>
                  </div>
                );
              })}
              {milestones.length === 0 && (
                <div className="py-20 text-center text-slate-400 border border-dashed border-slate-200 rounded-xl bg-slate-50/30">
                  등록된 마일스톤이 없습니다.
                </div>
              )}
              <div className="text-center py-4 text-[10px] text-slate-400 italic">
                * 마우스 휠을 사용하여 확대/축소하고, 화살표 버튼으로 타임라인을 이동할 수 있습니다.
              </div>
            </div>
          </div>
        )}
      </div>

      {/* Add/Edit Modal */}
      {(showAdd || editingMilestone) && (
        <div className="fixed inset-0 bg-slate-900/50 backdrop-blur-sm flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-2xl shadow-2xl w-full max-w-md animate-scaleIn overflow-hidden">
            <div className="p-6 border-b border-slate-100 bg-slate-50">
              <h3 className="text-lg font-bold">
                {editingMilestone ? '마일스톤 수정' : '새 마일스톤 추가'}
              </h3>
            </div>
            <div className="p-6 space-y-4">
              <div>
                <label className="block text-xs font-bold text-slate-400 uppercase mb-1">제목</label>
                <input 
                  type="text" 
                  value={formTitle} 
                  onChange={e => setFormTitle(e.target.value)}
                  className="w-full p-2.5 border border-slate-200 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none text-sm"
                />
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-xs font-bold text-slate-400 uppercase mb-1">시작일</label>
                  <input 
                    type="date" 
                    value={formStart} 
                    onChange={e => setFormStart(e.target.value)}
                    className="w-full p-2 border border-slate-200 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none text-sm"
                  />
                </div>
                <div>
                  <label className="block text-xs font-bold text-slate-400 uppercase mb-1">종료일</label>
                  <input 
                    type="date" 
                    value={formEnd} 
                    onChange={e => setFormEnd(e.target.value)}
                    className="w-full p-2 border border-slate-200 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none text-sm"
                  />
                </div>
              </div>
              {editingMilestone && (
                <div>
                  <label className="block text-xs font-bold text-slate-400 uppercase mb-1">진행 상태</label>
                  <select 
                    value={formStatus}
                    onChange={e => setFormStatus(e.target.value as any)}
                    className="w-full p-2 border border-slate-200 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none text-sm font-semibold"
                  >
                    <option value="UPCOMING">UPCOMING</option>
                    <option value="COMPLETED">COMPLETED</option>
                    <option value="OVERDUE">OVERDUE</option>
                  </select>
                </div>
              )}
            </div>
            <div className="p-6 bg-slate-50 flex justify-end gap-3">
              <div className="flex-1">
                {editingMilestone && (
                  <button type="button" onClick={(e) => { if(editingMilestone) { handleDelete(e, editingMilestone.id); setEditingMilestone(null); } }} className="px-4 py-2 text-sm text-red-500 hover:text-red-700 font-bold">삭제</button>
                )}
              </div>
              <button type="button" onClick={() => { setShowAdd(false); setEditingMilestone(null); }} className="px-4 py-2 text-sm text-slate-500 hover:text-slate-700">취소</button>
              <button type="button" onClick={editingMilestone ? handleSaveEdit : handleAdd} className="px-6 py-2 bg-blue-600 text-white rounded-lg text-sm font-bold shadow-lg hover:bg-blue-700">{editingMilestone ? '수정하기' : '추가하기'}</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { Project } from '../types';
import { PieChart, Pie, Cell, ResponsiveContainer, Tooltip, Legend } from 'recharts';
import { getStatus1Color, getStatus1ChartColor } from '../constants';

interface DashboardProps {
  projects: Project[];
  status1List: string[];
  status2List: string[];
  onSelect: (id: string) => void;
}

export const Dashboard: React.FC<DashboardProps> = ({ projects, status1List, status2List, onSelect }) => {
  // Filter States
  const [filterMode, setFilterMode] = useState<'ALL' | 'MONTH' | 'QUARTER' | 'YEAR' | 'CUSTOM'>('ALL');
  const [customStart, setCustomStart] = useState('');
  const [customEnd, setCustomEnd] = useState('');

  // New States for Chart Interaction
  const [selectedStatus1, setSelectedStatus1] = useState<string | null>(null);
  const [selectedStatuses2, setSelectedStatuses2] = useState<string[]>([]);

  // 1. 기간 필터만 적용된 기초 데이터 (차트용)
  const baseFilteredProjects = useMemo(() => {
    const now = new Date();
    const currentYear = now.getFullYear();
    const currentMonth = now.getMonth();

    return projects.filter(p => {
      const pStart = new Date(p.startDate);
      const pEnd = new Date(p.endDate);

      if (filterMode === 'MONTH') {
        return pStart.getFullYear() === currentYear && pStart.getMonth() === currentMonth;
      }
      if (filterMode === 'QUARTER') {
        const currentQuarter = Math.floor(currentMonth / 3);
        const pQuarter = Math.floor(pStart.getMonth() / 3);
        return pStart.getFullYear() === currentYear && pQuarter === currentQuarter;
      }
      if (filterMode === 'YEAR') {
        return pStart.getFullYear() === currentYear;
      }
      if (filterMode === 'CUSTOM') {
        const start = customStart ? new Date(customStart) : new Date(0);
        const end = customEnd ? new Date(customEnd) : new Date(8640000000000000);
        return pStart >= start && pEnd <= end;
      }
      return true;
    });
  }, [projects, filterMode, customStart, customEnd]);

  // 2. 1단계 상태(Pie Chart 클릭)로 필터링된 데이터 (2단계 통계용)
  const status1FilteredProjects = useMemo(() => {
    if (!selectedStatus1) return baseFilteredProjects;
    return baseFilteredProjects.filter(p => p.status1 === selectedStatus1);
  }, [baseFilteredProjects, selectedStatus1]);

  // 3. 2단계 다중 선택까지 적용된 최종 데이터 (하단 목록용)
  const displayProjects = useMemo(() => {
    let result = status1FilteredProjects;
    if (selectedStatuses2.length > 0) {
      result = result.filter(p => selectedStatuses2.includes(p.status2));
    }
    return result;
  }, [status1FilteredProjects, selectedStatuses2]);

  // 차트 데이터 구성
  const status1Map = status1List.reduce((acc, s) => {
    acc[s] = baseFilteredProjects.filter(p => p.status1 === s).length;
    return acc;
  }, {} as Record<string, number>);

  const status1Data = Object.entries(status1Map).map(([name, value]) => ({
    name,
    value: value as number,
    color: getStatus1ChartColor(name)
  })).filter(d => (d.value as number) >= 0);

  // 2단계 현황 데이터 (선택된 1단계에 따라 변화)
  const status2Map = status1FilteredProjects.reduce((acc, p) => {
    acc[p.status2] = (acc[p.status2] || 0) + 1;
    return acc;
  }, {} as Record<string, number>);

  const status2Data = status2List.map(name => ({
    name,
    value: status2Map[name] || 0
  }));

  const handleExport = () => {
    const headers = ['프로젝트명', 'PM', '1단계 상태', '2단계 상세', '시작일', '종료일', '설명'];
    const rows = displayProjects.map(p => [
      p.name,
      p.manager,
      p.status1,
      p.status2,
      p.startDate,
      p.endDate,
      p.description.replace(/,/g, ' ')
    ]);

    const csvContent = ['\ufeff' + headers.join(','), ...rows.map(e => e.join(','))].join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `Project_Report_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  };

  const onPieClick = (data: any) => {
    if (data && data.name) {
      setSelectedStatus1(prev => prev === data.name ? null : data.name);
      setSelectedStatuses2([]); // 1단계 변경 시 2단계 필터 초기화
    }
  };

  const toggleStatus2 = (name: string) => {
    setSelectedStatuses2(prev => 
      prev.includes(name) 
        ? prev.filter(s => s !== name) 
        : [...prev, name]
    );
  };

  const renderCustomizedLabel = ({ cx, cy, midAngle, innerRadius, outerRadius, value, name }: any) => {
    const RADIAN = Math.PI / 180;
    const radius = Number(innerRadius) + (Number(outerRadius) - Number(innerRadius)) * 0.5;
    const x = Number(cx) + radius * Math.cos(-Number(midAngle) * RADIAN);
    const y = Number(cy) + radius * Math.sin(-Number(midAngle) * RADIAN);

    return (
      <text x={x} y={y} fill="white" textAnchor="middle" dominantBaseline="central" className="text-[10px] font-bold">
        {value > 0 ? `${value}` : ''}
      </text>
    );
  };

  return (
    <div className="space-y-6 animate-fadeIn">
      {/* Header */}
      <header className="flex flex-col md:flex-row justify-between items-start md:items-end gap-4">
        <div>
          <h2 className="text-3xl font-bold tracking-tight">전체 프로젝트 대시보드</h2>
          <p className="text-slate-500">프로젝트 진행 현황 및 드릴다운 분석</p>
        </div>
        <button 
          onClick={handleExport}
          className="flex items-center gap-2 px-4 py-2.5 bg-green-600 text-white text-sm font-bold rounded-xl hover:bg-green-700 transition-all shadow-lg shadow-green-100"
        >
          <span>📥</span> 엑셀로 내보내기 ({displayProjects.length})
        </button>
      </header>

      {/* Filter Bar */}
      <div className="bg-white p-4 rounded-2xl border border-slate-200 shadow-sm flex flex-wrap items-center gap-6">
        <div className="flex items-center gap-2">
          <span className="text-xs font-bold text-slate-400 uppercase tracking-widest">기간 조회</span>
          <div className="flex bg-slate-100 p-1 rounded-lg">
            {(['ALL', 'MONTH', 'QUARTER', 'YEAR', 'CUSTOM'] as const).map(mode => (
              <button
                key={mode}
                onClick={() => { setFilterMode(mode); setSelectedStatus1(null); setSelectedStatuses2([]); }}
                className={`px-3 py-1.5 text-xs font-bold rounded-md transition-all ${
                  filterMode === mode ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'
                }`}
              >
                {mode === 'ALL' ? '전체' : mode === 'MONTH' ? '이번 달' : mode === 'QUARTER' ? '분기' : mode === 'YEAR' ? '올해' : '사용자 정의'}
              </button>
            ))}
          </div>
        </div>

        {filterMode === 'CUSTOM' && (
          <div className="flex items-center gap-2 animate-slideDown">
            <input type="date" value={customStart} onChange={e => setCustomStart(e.target.value)} className="p-1.5 text-xs border border-slate-200 rounded-md" />
            <span className="text-slate-300">~</span>
            <input type="date" value={customEnd} onChange={e => setCustomEnd(e.target.value)} className="p-1.5 text-xs border border-slate-200 rounded-md" />
          </div>
        )}

        {selectedStatus1 && (
          <div className="flex items-center gap-2 bg-blue-50 px-3 py-1.5 rounded-lg border border-blue-100 animate-slideRight">
            <span className="text-xs font-bold text-blue-600">
              1단계 필터: {selectedStatus1}
            </span>
            <button onClick={() => setSelectedStatus1(null)} className="text-blue-400 hover:text-blue-600 text-xs font-bold ml-1">✕</button>
          </div>
        )}

        <div className="ml-auto text-xs font-medium text-slate-400">
          기준 프로젝트: <span className="font-bold text-slate-900">{baseFilteredProjects.length}</span>건 / 
          현재 필터: <span className="font-bold text-blue-600">{displayProjects.length}</span>건
        </div>
      </div>

      {/* Charts Section */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Pie Chart */}
        <div className="bg-white p-8 rounded-2xl shadow-sm border border-slate-200 flex flex-col h-[450px]">
          <div className="flex justify-between items-start mb-4">
            <div>
              <h3 className="font-bold text-slate-800">1단계 상태 분포</h3>
              <p className="text-[11px] text-slate-400">차트 조각을 클릭하면 하위 프로세스를 필터링합니다.</p>
            </div>
            {selectedStatus1 && (
              <button onClick={() => setSelectedStatus1(null)} className="text-[10px] font-bold text-blue-600 bg-blue-50 px-2 py-1 rounded">필터 초기화</button>
            )}
          </div>
          <div className="flex-1">
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie 
                  data={status1Data} 
                  cx="50%" 
                  cy="45%" 
                  labelLine={false} 
                  label={renderCustomizedLabel} 
                  outerRadius={110} 
                  dataKey="value"
                  onClick={onPieClick}
                  style={{ cursor: 'pointer' }}
                >
                  {status1Data.map((entry, index) => (
                    <Cell 
                      key={`cell-${index}`} 
                      fill={entry.color} 
                      stroke={selectedStatus1 === entry.name ? '#000' : 'none'}
                      strokeWidth={2}
                      opacity={selectedStatus1 && selectedStatus1 !== entry.name ? 0.4 : 1}
                    />
                  ))}
                </Pie>
                <Tooltip 
                  contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgba(0,0,0,0.1)' }}
                  formatter={(value: number, name: string) => [`${value}건`, name]}
                />
                <Legend verticalAlign="bottom" />
              </PieChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* Interactive Progress List */}
        <div className="bg-white p-8 rounded-2xl shadow-sm border border-slate-200 flex flex-col h-[450px]">
          <div className="flex justify-between items-start mb-2">
            <div>
              <h3 className="font-bold text-slate-800">
                {selectedStatus1 ? `${selectedStatus1} 상태의 ` : '전체 '} 
                2단계 상세 프로세스 현황
              </h3>
              <p className="text-[11px] text-slate-400">
                {selectedStatus1 ? `${selectedStatus1} 단계에 있는 ${status1FilteredProjects.length}건의 분석입니다.` : '모든 프로젝트의 현재 공정률 분석입니다.'}
              </p>
            </div>
            <div className="flex gap-2">
               <button 
                  onClick={() => setSelectedStatuses2([])}
                  className="text-[10px] font-bold text-slate-400 hover:text-slate-600 px-2 py-1"
                >
                  필터 해제
                </button>
            </div>
          </div>

          <div className="flex-1 overflow-y-auto pr-2 custom-scrollbar mt-4">
            <div className="space-y-2">
              {status2Data.map((item, idx) => {
                const totalSteps = status2List.length;
                const progressPercent = ((idx + 1) / totalSteps) * 100;
                const isSelected = selectedStatuses2.includes(item.name);
                const hasProjects = item.value > 0;

                return (
                  <div 
                    key={idx} 
                    onClick={() => toggleStatus2(item.name)}
                    className={`p-3 rounded-xl border transition-all cursor-pointer group flex flex-col ${
                      isSelected ? 'bg-blue-50 border-blue-200 shadow-sm ring-1 ring-blue-100' : 
                      hasProjects ? 'bg-white border-transparent hover:bg-slate-50' : 'opacity-30 grayscale'
                    }`}
                  >
                    <div className="flex justify-between items-center mb-2">
                      <div className="flex items-center gap-2">
                        <div className={`w-3 h-3 rounded border flex items-center justify-center transition-colors ${isSelected ? 'bg-blue-600 border-blue-600' : 'border-slate-300'}`}>
                          {isSelected && <span className="text-[8px] text-white">✓</span>}
                        </div>
                        <span className={`text-sm font-bold ${isSelected ? 'text-blue-700' : 'text-slate-700'}`}>{item.name}</span>
                        <span className="text-[10px] text-slate-400 font-mono">({idx + 1}/{totalSteps})</span>
                      </div>
                      <span className={`text-xs font-black ${hasProjects ? (isSelected ? 'text-blue-600' : 'text-slate-900') : 'text-slate-300'}`}>
                        {item.value}건
                      </span>
                    </div>
                    <div className="w-full bg-slate-100 h-1 rounded-full overflow-hidden">
                      <div 
                        className={`h-full transition-all duration-700 ${isSelected ? 'bg-blue-600' : 'bg-blue-400'}`}
                        style={{ width: `${progressPercent}%` }}
                      />
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
        </div>
      </div>

      {/* List Table */}
      <div className="bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden">
        <div className="px-8 py-5 border-b border-slate-100 bg-slate-50/50 flex justify-between items-center">
          <div className="flex items-center gap-3">
            <h3 className="font-bold text-slate-800">
              프로젝트 목록 ({displayProjects.length})
            </h3>
            <div className="flex gap-2">
              {selectedStatus1 && (
                <span className="text-[10px] font-bold text-blue-600 bg-blue-100/50 px-2 py-0.5 rounded-full">
                  1단계: {selectedStatus1}
                </span>
              )}
              {selectedStatuses2.length > 0 && (
                <span className="text-[10px] font-bold text-purple-600 bg-purple-100/50 px-2 py-0.5 rounded-full">
                  2단계: {selectedStatuses2.length}개 선택됨
                </span>
              )}
            </div>
          </div>
        </div>
        <div className="overflow-x-auto">
          <table className="w-full text-left border-collapse">
            <thead>
              <tr className="bg-white text-[11px] font-bold text-slate-400 uppercase tracking-widest border-b border-slate-50">
                <th className="px-8 py-4">프로젝트명</th>
                <th className="px-8 py-4">PM</th>
                <th className="px-8 py-4">상세 상태</th>
                <th className="px-8 py-4 text-right">기간</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50 text-sm">
              {displayProjects.map(p => (
                <tr key={p.id} onClick={() => onSelect(p.id)} className="group hover:bg-slate-50 cursor-pointer">
                  <td className="px-8 py-4">
                    <div className="flex items-center gap-3">
                      <span className={`w-2 h-2 rounded-full ${p.status1 === 'DONE' ? 'bg-green-500' : 'bg-blue-500'}`} />
                      <div className="font-bold text-slate-700 group-hover:text-blue-600">{p.name}</div>
                    </div>
                  </td>
                  <td className="px-8 py-4 text-slate-500">{p.manager}</td>
                  <td className="px-8 py-4">
                    <span className="text-[10px] font-bold text-slate-400 bg-slate-100 px-1.5 py-0.5 rounded uppercase">{p.status1} / {p.status2}</span>
                  </td>
                  <td className="px-8 py-4 text-right font-mono text-[11px] text-slate-400">{p.startDate} ~ {p.endDate}</td>
                </tr>
              ))}
              {displayProjects.length === 0 && (
                <tr>
                  <td colSpan={4} className="py-20 text-center text-slate-400 italic">필터 조건에 맞는 데이터가 없습니다.</td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

import { Project } from '../types';
import { PieChart, Pie, Cell, ResponsiveContainer, Tooltip, Legend } from 'recharts';
import { getStatus1Color, getStatus1ChartColor } from '../constants';

interface DashboardProps {
  projects: Project[];
  status1List: string[];
  status2List: string[];
  onSelect: (id: string) => void;
}

export const Dashboard: React.FC<DashboardProps> = ({ projects, status1List, status2List, onSelect }) => {
  // Filter States
  const [filterMode, setFilterMode] = useState<'ALL' | 'MONTH' | 'QUARTER' | 'YEAR' | 'CUSTOM'>('ALL');
  const [customStart, setCustomStart] = useState('');
  const [customEnd, setCustomEnd] = useState('');

  // States for Chart Interaction
  const [selectedStatus1, setSelectedStatus1] = useState<string | null>(null);
  const [selectedStatuses2, setSelectedStatuses2] = useState<string[]>([]);

  // 1. 기초 데이터 필터링
  const baseFilteredProjects = useMemo(() => {
    const now = new Date();
    const currentYear = now.getFullYear();
    const currentMonth = now.getMonth();

    return projects.filter(p => {
      const pStart = new Date(p.startDate);
      const pEnd = new Date(p.endDate);

      if (filterMode === 'MONTH') {
        return pStart.getFullYear() === currentYear && pStart.getMonth() === currentMonth;
      }
      if (filterMode === 'QUARTER') {
