        {activeTab === 'OVERVIEW' && (
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
            <div className="lg:col-span-2 bg-white p-6 rounded-2xl border border-slate-200 shadow-sm">
              <div className="flex justify-between items-center mb-6">
                <h3 className="font-bold text-slate-800">상세 요구사항</h3>
                <button onClick={() => handleAutoGenerate('REQUIREMENTS')} className="text-[10px] font-black text-blue-600 bg-blue-50 px-3 py-1.5 rounded-lg uppercase tracking-tighter" disabled={isGenerating}>
                  {isGenerating ? 'AI 분석 중...' : '✨ AI 생성'}
