import React, { useState, useMemo } from 'react';
import { Milestone, ViewType, ScaleType } from '../types';

interface MilestoneViewProps {
  milestones: Milestone[];
  onUpdateMilestones: (milestones: Milestone[]) => void;
}

export const MilestoneView: React.FC<MilestoneViewProps> = ({ milestones, onUpdateMilestones }) => {
  const [view, setView] = useState<ViewType>('LIST');
  const [scale, setScale] = useState<ScaleType>('MONTH');
  const [viewDate, setViewDate] = useState(new Date());
  const [ganttBaseDate, setGanttBaseDate] = useState(new Date());
  const [showAdd, setShowAdd] = useState(false);
  const [editingMilestone, setEditingMilestone] = useState<Milestone | null>(null);

  const [formTitle, setFormTitle] = useState('');
  const [formStart, setFormStart] = useState('');
  const [formEnd, setFormEnd] = useState('');
  const [formStatus, setFormStatus] = useState<Milestone['status']>('UPCOMING');

  const openAddModal = () => { setFormTitle(''); setFormStart(''); setFormEnd(''); setFormStatus('UPCOMING'); setShowAdd(true); };
  const openEditModal = (m: Milestone) => { setEditingMilestone(m); setFormTitle(m.title); setFormStart(m.startDate); setFormEnd(m.endDate); setFormStatus(m.status); };

  const handleAdd = () => {
    if (!formTitle || !formStart || !formEnd) return;
    onUpdateMilestones([...milestones, { id: Math.random().toString(36).substr(2, 9), title: formTitle, startDate: formStart, endDate: formEnd, status: 'UPCOMING' }]);
    setShowAdd(false);
  };

  const handleSaveEdit = () => {
    if (!editingMilestone) return;
    onUpdateMilestones(milestones.map(m => m.id === editingMilestone.id ? { ...m, title: formTitle, startDate: formStart, endDate: formEnd, status: formStatus } : m));
    setEditingMilestone(null);
  };

  const handleDelete = (id: string) => {
    if (window.confirm('삭제하시겠습니까?')) onUpdateMilestones(milestones.filter(m => m.id !== id));
  };

  const calendarDates = useMemo(() => {
    const start = new Date(viewDate.getFullYear(), viewDate.getMonth(), 1);
    const startDay = start.getDay();
    const startDate = new Date(start);
    startDate.setDate(start.getDate() - startDay);
    return Array.from({ length: 42 }).map((_, i) => {
      const d = new Date(startDate);
      d.setDate(startDate.getDate() + i);
      return d;
    });
  }, [viewDate]);

  const ganttConfig = useMemo(() => {
    let units = [];
    let startRange: Date, endRange: Date;
    if (scale === 'DAY') {
      startRange = new Date(ganttBaseDate); startRange.setHours(0,0,0,0);
      for (let i = 0; i < 14; i++) { const d = new Date(startRange); d.setDate(startRange.getDate() + i); units.push(`${d.getMonth()+1}/${d.getDate()}`); }
      endRange = new Date(startRange); endRange.setDate(startRange.getDate() + 14);
    } else if (scale === 'MONTH') {
      startRange = new Date(ganttBaseDate.getFullYear(), 0, 1);
      for (let i = 1; i <= 12; i++) units.push(`${i}월`);
      endRange = new Date(ganttBaseDate.getFullYear(), 11, 31);
    } else {
      startRange = new Date(ganttBaseDate.getFullYear(), 0, 1);
      for (let i = 1; i <= 4; i++) units.push(`${i}Q`);
      endRange = new Date(ganttBaseDate.getFullYear(), 11, 31);
    }
    return { units, startRange, endRange };
  }, [scale, ganttBaseDate]);

  const calculateGanttStyle = (m: Milestone) => {
    const { startRange, endRange } = ganttConfig;
    const mStart = new Date(m.startDate); const mEnd = new Date(m.endDate);
    const total = endRange.getTime() - startRange.getTime();
    let left = ((mStart.getTime() - startRange.getTime()) / total) * 100;
    let width = ((mEnd.getTime() - mStart.getTime()) / total) * 100;
    if (left + width < 0 || left > 100) return { display: 'none' };
    return { left: `${Math.max(0, left)}%`, width: `${Math.min(100, width)}%` };
  };

  return (
    <div className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden flex flex-col">
      {/* Controls Bar */}
      <div className="p-4 border-b border-slate-100 bg-slate-50/50 flex flex-col sm:flex-row justify-between items-center gap-4">
        <div className="flex bg-slate-200/50 p-1 rounded-xl w-full sm:w-auto">
          {(['LIST', 'CALENDAR', 'GANTT'] as ViewType[]).map(v => (
            <button key={v} onClick={() => setView(v)} className={`flex-1 px-4 py-2 text-[11px] font-bold rounded-lg transition-all ${view === v ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500 hover:text-slate-800'}`}>
              {v}
            </button>
          ))}
        </div>

        {view !== 'LIST' && (
          <div className="flex items-center gap-3">
            <button onClick={() => {
              const d = new Date(view === 'CALENDAR' ? viewDate : ganttBaseDate);
              d.setMonth(d.getMonth() - 1);
              view === 'CALENDAR' ? setViewDate(d) : setGanttBaseDate(d);
            }} className="p-2 bg-white border border-slate-200 rounded-lg text-xs">◀</button>
            <span className="text-xs font-bold text-slate-700 min-w-[80px] text-center">
              {view === 'CALENDAR' ? `${viewDate.getFullYear()}.${viewDate.getMonth()+1}` : `${ganttBaseDate.getFullYear()}`}
            </span>
            <button onClick={() => {
              const d = new Date(view === 'CALENDAR' ? viewDate : ganttBaseDate);
              d.setMonth(d.getMonth() + 1);
              view === 'CALENDAR' ? setViewDate(d) : setGanttBaseDate(d);
            }} className="p-2 bg-white border border-slate-200 rounded-lg text-xs">▶</button>
          </div>
        )}

        <button onClick={openAddModal} className="w-full sm:w-auto px-4 py-2.5 bg-blue-600 text-white text-[11px] font-bold rounded-xl shadow-lg shadow-blue-100">+ 추가</button>
      </div>

      <div className="p-4 overflow-x-auto min-h-[400px]">
        {view === 'LIST' && (
          <table className="w-full text-left min-w-[500px]">
            <thead>
              <tr className="text-[10px] text-slate-400 font-black uppercase tracking-widest border-b border-slate-50">
                <th className="pb-3 px-2">태스크</th>
                <th className="pb-3 px-2 text-center">상태</th>
                <th className="pb-3 px-2 text-right">기한</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {milestones.map(m => (
                <tr key={m.id} onClick={() => openEditModal(m)} className="text-sm group hover:bg-slate-50 cursor-pointer">
                  <td className="py-4 px-2 font-bold text-slate-700">{m.title}</td>
                  <td className="py-4 px-2 text-center">
                    <span className={`px-2 py-0.5 rounded text-[10px] font-bold ${m.status === 'COMPLETED' ? 'bg-green-100 text-green-700' : 'bg-blue-100 text-blue-700'}`}>{m.status}</span>
                  </td>
                  <td className="py-4 px-2 text-right text-[11px] font-mono text-slate-400">{m.startDate} ~ {m.endDate}</td>
                </tr>
              ))}
            </tbody>
          </table>
        )}

        {view === 'CALENDAR' && (
           <div className="min-w-[700px]">
             <div className="grid grid-cols-7 gap-1">
               {['SUN', 'MON', 'TUE', 'WED', 'THU', 'FRI', 'SAT'].map(d => <div key={d} className="text-center text-[10px] font-black text-slate-400 py-2 uppercase">{d}</div>)}
               {calendarDates.map((date, i) => (
                 <div key={i} className={`bg-slate-50/50 min-h-[100px] p-2 rounded-xl border border-white transition-all hover:bg-white hover:shadow-sm ${date.getMonth() !== viewDate.getMonth() ? 'opacity-30' : ''}`}>
                    <span className="text-[10px] font-bold text-slate-500">{date.getDate()}</span>
                    <div className="mt-1 space-y-1">
                      {milestones.map(m => {
                        const mS = new Date(m.startDate); const mE = new Date(m.endDate);
                        if (date >= mS && date <= mE) return <div key={m.id} onClick={() => openEditModal(m)} className="p-1 text-[8px] font-bold bg-blue-500 text-white rounded truncate">{m.title}</div>;
                        return null;
                      })}
                    </div>
                 </div>
               ))}
             </div>
           </div>
        )}

        {view === 'GANTT' && (
           <div className="min-w-[800px] space-y-6">
             <div className="flex border-b border-slate-100 bg-slate-50 p-2 rounded-xl">
               <div className="w-40 text-[10px] font-black text-slate-400">Task Name</div>
               <div className="flex-1 flex justify-around">
                 {ganttConfig.units.map((u, i) => <span key={i} className="text-[9px] font-bold text-slate-400">{u}</span>)}
               </div>
             </div>
             {milestones.map(m => (
               <div key={m.id} className="flex items-center gap-4">
                 <div className="w-40 truncate text-sm font-bold text-slate-700">{m.title}</div>
                 <div className="flex-1 h-8 bg-slate-50 rounded-lg relative overflow-hidden border border-slate-100 shadow-inner">
                   <div className={`absolute h-full bg-blue-500 rounded-lg flex items-center px-2 text-[9px] text-white font-bold shadow-md`} style={calculateGanttStyle(m)}>{m.title}</div>
                 </div>
               </div>
             ))}
           </div>
        )}
      </div>

      {/* Basic Modal Implementation */}
      {(showAdd || editingMilestone) && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[100] flex items-center justify-center p-4">
          <div className="bg-white rounded-3xl w-full max-w-sm overflow-hidden shadow-2xl animate-scaleIn">
            <div className="p-6 border-b border-slate-50 flex justify-between items-center bg-slate-50">
              <h3 className="font-bold text-slate-800">{editingMilestone ? '수정' : '추가'}</h3>
              <button onClick={() => {setShowAdd(false); setEditingMilestone(null);}} className="text-slate-400">✕</button>
            </div>
            <div className="p-6 space-y-4">
              <input value={formTitle} onChange={e => setFormTitle(e.target.value)} className="w-full p-3 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-blue-500" placeholder="태스크명" />
              <div className="grid grid-cols-2 gap-3">
                <input type="date" value={formStart} onChange={e => setFormStart(e.target.value)} className="w-full p-2 border border-slate-200 rounded-lg text-xs" />
                <input type="date" value={formEnd} onChange={e => setFormEnd(e.target.value)} className="w-full p-2 border border-slate-200 rounded-lg text-xs" />
              </div>
              <button onClick={editingMilestone ? handleSaveEdit : handleAdd} className="w-full py-3 bg-blue-600 text-white rounded-xl font-bold">{editingMilestone ? '업데이트' : '확인'}</button>
              {editingMilestone && <button onClick={() => handleDelete(editingMilestone.id)} className="w-full py-2 text-xs text-red-500 font-bold">삭제</button>}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { Project } from '../types';

interface SidebarProps {
  projects: Project[];
  selectedId: string | null;
  onSelectProject: (id: string | null) => void;
  onNavigate: (view: 'DASHBOARD' | 'SETTINGS') => void;
  isOpen: boolean;
  onClose: () => void;
}

export const Sidebar: React.FC<SidebarProps> = ({ projects, selectedId, onSelectProject, onNavigate, isOpen, onClose }) => {
  // 섹션 확장/축소 상태 관리
  const [expandedSections, setExpandedSections] = useState<Record<string, boolean>>({
    TODO: true,
    IN_PROGRESS: true,
    DONE: false
  });

  const toggleSection = (section: string) => {
    setExpandedSections(prev => ({ ...prev, [section]: !prev[section] }));
  };

  // 프로젝트 그룹화 로직
  const groupedProjects = useMemo(() => {
    const groups: Record<string, Project[]> = {
      TODO: [],
      IN_PROGRESS: [],
      DONE: [],
      OTHER: []
    };

    projects.forEach(p => {
      const s1 = p.status1.toUpperCase();
      if (s1.includes('TODO') || s1.includes('대기')) groups.TODO.push(p);
      else if (s1.includes('PROGRESS') || s1.includes('진행')) groups.IN_PROGRESS.push(p);
      else if (s1.includes('DONE') || s1.includes('완료')) groups.DONE.push(p);
      else groups.OTHER.push(p);
    });

    return groups;
  }, [projects]);

  // 진행 중인 프로젝트를 2단계 상태별로 재그룹화
  const inProgressSubGroups = useMemo(() => {
    const sub: Record<string, Project[]> = {};
    groupedProjects.IN_PROGRESS.forEach(p => {
      if (!sub[p.status2]) sub[p.status2] = [];
      sub[p.status2].push(p);
    });
    return sub;
  }, [groupedProjects.IN_PROGRESS]);

  const renderProjectItem = (p: Project) => (
    <button
      key={p.id}
      onClick={() => onSelectProject(p.id)}
      className={`w-full text-left px-3 py-2 rounded-lg transition-all text-xs truncate flex items-center gap-2 group/item ${
        selectedId === p.id 
          ? 'bg-blue-600 text-white shadow-md' 
          : 'hover:bg-slate-800 text-slate-400 hover:text-slate-200'
      }`}
    >
      <span className={`w-1.5 h-1.5 rounded-full shrink-0 ${selectedId === p.id ? 'bg-white' : 'bg-slate-600 group-hover/item:bg-slate-400'}`} />
      <span className="truncate flex-1">{p.name}</span>
      {selectedId !== p.id && <span className="text-[9px] opacity-0 group-hover/item:opacity-100 text-slate-500">보기</span>}
    </button>
  );

  return (
    <>
      {/* Overlay for mobile */}
      {isOpen && (
        <div 
          className="fixed inset-0 bg-black/60 z-[55] lg:hidden backdrop-blur-sm transition-opacity"
          onClick={onClose}
        />
      )}

      <div className={`
        fixed left-0 top-0 bottom-0 w-64 bg-slate-900 text-white z-[60] flex flex-col transition-transform duration-300 ease-in-out border-r border-slate-800
        ${isOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}
      `}>
        <div className="p-6 border-b border-slate-800 flex justify-between items-center">
          <div className="flex items-center gap-2">
            <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center font-black text-xl">P</div>
            <h1 className="text-lg font-bold tracking-tight">PM Master</h1>
          </div>
          <button onClick={onClose} className="lg:hidden text-slate-400 p-2 hover:bg-slate-800 rounded-md">✕</button>
        </div>

        <nav className="flex-1 overflow-y-auto py-4 px-3 space-y-6 custom-scrollbar">
          {/* Main Navigation */}
          <div className="space-y-1">
            <button 
              onClick={() => onNavigate('DASHBOARD')}
              className="w-full text-left px-4 py-3 rounded-xl transition hover:bg-slate-800 flex items-center gap-3 text-sm font-bold group"
            >
              <span className="text-lg group-hover:scale-110 transition-transform">📊</span> 
              <span className="text-slate-300 group-hover:text-white">통합 대시보드</span>
            </button>
          </div>

          {/* Projects Grouped by Status */}
          <div className="space-y-4">
            {/* 1. TODO Section */}
            <div>
              <button 
                onClick={() => toggleSection('TODO')}
                className="w-full flex items-center justify-between px-3 mb-2 text-[10px] font-black text-slate-500 uppercase tracking-[0.15em] hover:text-slate-300 transition-colors"
              >
                <span className="flex items-center gap-2">
                  <span className="w-1.5 h-1.5 rounded-full bg-slate-500" />
                  진행 대기 ({groupedProjects.TODO.length})
                </span>
                <span>{expandedSections.TODO ? '▾' : '▸'}</span>
              </button>
              {expandedSections.TODO && (
                <div className="space-y-0.5 ml-2 animate-fadeIn">
                  {groupedProjects.TODO.map(renderProjectItem)}
                  {groupedProjects.TODO.length === 0 && <div className="px-4 py-2 text-[10px] text-slate-600 italic">대기중인 프로젝트 없음</div>}
                </div>
              )}
            </div>

            {/* 2. IN PROGRESS Section (with Sub-groups) */}
            <div>
              <button 
                onClick={() => toggleSection('IN_PROGRESS')}
                className="w-full flex items-center justify-between px-3 mb-2 text-[10px] font-black text-blue-400 uppercase tracking-[0.15em] hover:text-blue-300 transition-colors"
              >
                <span className="flex items-center gap-2">
                  <span className="w-1.5 h-1.5 rounded-full bg-blue-500 animate-pulse" />
                  실시간 진행 중 ({groupedProjects.IN_PROGRESS.length})
                </span>
                <span>{expandedSections.IN_PROGRESS ? '▾' : '▸'}</span>
              </button>
              {expandedSections.IN_PROGRESS && (
                <div className="space-y-4 ml-2 animate-fadeIn">
                  {Object.entries(inProgressSubGroups).map(([status2, projs]) => (
                    <div key={status2} className="space-y-1">
                      <div className="px-3 py-1 flex justify-between items-center bg-slate-800/40 rounded-md mb-1">
                        <span className="text-[9px] font-bold text-slate-400">{status2}</span>
                        <span className="text-[9px] font-bold text-slate-500">{projs.length}</span>
                      </div>
                      <div className="space-y-0.5">
                        {projs.map(renderProjectItem)}
                      </div>
                    </div>
                  ))}
                  {groupedProjects.IN_PROGRESS.length === 0 && <div className="px-4 py-2 text-[10px] text-slate-600 italic">진행 중인 프로젝트 없음</div>}
                </div>
              )}
            </div>

            {/* 3. DONE Section */}
            <div>
              <button 
                onClick={() => toggleSection('DONE')}
                className="w-full flex items-center justify-between px-3 mb-2 text-[10px] font-black text-green-500 uppercase tracking-[0.15em] hover:text-green-300 transition-colors"
              >
                <span className="flex items-center gap-2">
                  <span className="w-1.5 h-1.5 rounded-full bg-green-500" />
                  완료된 프로젝트 ({groupedProjects.DONE.length})
                </span>
                <span>{expandedSections.DONE ? '▾' : '▸'}</span>
              </button>
              {expandedSections.DONE && (
                <div className="space-y-0.5 ml-2 animate-fadeIn">
                  {groupedProjects.DONE.map(renderProjectItem)}
                  {groupedProjects.DONE.length === 0 && <div className="px-4 py-2 text-[10px] text-slate-600 italic">완료된 프로젝트 없음</div>}
                </div>
              )}
            </div>
          </div>
        </nav>

        <div className="p-4 border-t border-slate-800">
          <button 
            onClick={() => onNavigate('SETTINGS')}
            className="w-full text-left px-4 py-3 rounded-xl transition hover:bg-slate-800 flex items-center gap-3 text-slate-400 text-sm font-medium group"
          >
            <span className="group-hover:rotate-45 transition-transform">⚙️</span> 
            <span className="group-hover:text-slate-200">워크플로우 구성</span>
          </button>
        </div>
      </div>
    </>
  );
};

import React, { useState, useMemo } from 'react';
import { Milestone, ViewType, ScaleType } from '../types';

interface MilestoneViewProps {
  milestones: Milestone[];
  onUpdateMilestones: (milestones: Milestone[]) => void;
}

export const MilestoneView: React.FC<MilestoneViewProps> = ({ milestones, onUpdateMilestones }) => {
  const [view, setView] = useState<ViewType>('LIST');
  const [scale, setScale] = useState<ScaleType>('MONTH');
  const [viewDate, setViewDate] = useState(new Date());
  const [ganttBaseDate, setGanttBaseDate] = useState(new Date());
  const [showAdd, setShowAdd] = useState(false);
  const [editingMilestone, setEditingMilestone] = useState<Milestone | null>(null);

  const [formTitle, setFormTitle] = useState('');
  const [formStart, setFormStart] = useState('');
  const [formEnd, setFormEnd] = useState('');
  const [formStatus, setFormStatus] = useState<Milestone['status']>('UPCOMING');

  const openAddModal = () => { 
    setFormTitle(''); 
    setFormStart(''); 
    setFormEnd(''); 
    setFormStatus('UPCOMING'); 
    setShowAdd(true); 
  };

  const openEditModal = (m: Milestone) => { 
    setEditingMilestone(m); 
    setFormTitle(m.title); 
    setFormStart(m.startDate); 
    setFormEnd(m.endDate); 
    setFormStatus(m.status); 
  };

  const handleAdd = () => {
    if (!formTitle || !formStart || !formEnd) return;
    const newMilestone: Milestone = { 
      id: Math.random().toString(36).substr(2, 9), 
      title: formTitle, 
      startDate: formStart, 
      endDate: formEnd, 
      status: 'UPCOMING' 
    };
    onUpdateMilestones([...milestones, newMilestone]);
    setShowAdd(false);
  };

  const handleSaveEdit = () => {
    if (!editingMilestone) return;
    onUpdateMilestones(milestones.map(m => 
      m.id === editingMilestone.id 
        ? { ...m, title: formTitle, startDate: formStart, endDate: formEnd, status: formStatus } 
        : m
    ));
    setEditingMilestone(null);
  };

  const handleDelete = (id: string) => {
    if (window.confirm('이 마일스톤을 삭제하시겠습니까?')) {
      onUpdateMilestones(milestones.filter(m => m.id !== id));
      setEditingMilestone(null); // 삭제 후 모달 닫기
    }
  };

  const calendarDates = useMemo(() => {
    const start = new Date(viewDate.getFullYear(), viewDate.getMonth(), 1);
    const startDay = start.getDay();
    const startDate = new Date(start);
    startDate.setDate(start.getDate() - startDay);
    return Array.from({ length: 42 }).map((_, i) => {
      const d = new Date(startDate);
      d.setDate(startDate.getDate() + i);
      return d;
    });
  }, [viewDate]);

  const ganttConfig = useMemo(() => {
    let units = [];
    let startRange: Date, endRange: Date;
    if (scale === 'DAY') {
      startRange = new Date(ganttBaseDate); startRange.setHours(0,0,0,0);
      for (let i = 0; i < 14; i++) { const d = new Date(startRange); d.setDate(startRange.getDate() + i); units.push(`${d.getMonth()+1}/${d.getDate()}`); }
      endRange = new Date(startRange); endRange.setDate(startRange.getDate() + 14);
    } else if (scale === 'MONTH') {
      startRange = new Date(ganttBaseDate.getFullYear(), 0, 1);
      for (let i = 1; i <= 12; i++) units.push(`${i}월`);
      endRange = new Date(ganttBaseDate.getFullYear(), 11, 31);
    } else {
      startRange = new Date(ganttBaseDate.getFullYear(), 0, 1);
      for (let i = 1; i <= 4; i++) units.push(`${i}Q`);
      endRange = new Date(ganttBaseDate.getFullYear(), 11, 31);
    }
    return { units, startRange, endRange };
  }, [scale, ganttBaseDate]);

  const calculateGanttStyle = (m: Milestone) => {
    const { startRange, endRange } = ganttConfig;
    const mStart = new Date(m.startDate); const mEnd = new Date(m.endDate);
    const total = endRange.getTime() - startRange.getTime();
    let left = ((mStart.getTime() - startRange.getTime()) / total) * 100;
    let width = ((mEnd.getTime() - mStart.getTime()) / total) * 100;
    if (left + width < 0 || left > 100) return { display: 'none' };
    return { left: `${Math.max(0, left)}%`, width: `${Math.min(100, width)}%` };
  };

  return (
    <div className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden flex flex-col">
      {/* Controls Bar */}
      <div className="p-4 border-b border-slate-100 bg-slate-50/50 flex flex-col sm:flex-row justify-between items-center gap-4">
        <div className="flex bg-slate-200/50 p-1 rounded-xl w-full sm:w-auto">
          {(['LIST', 'CALENDAR', 'GANTT'] as ViewType[]).map(v => (
            <button key={v} onClick={() => setView(v)} className={`flex-1 px-4 py-2 text-[11px] font-bold rounded-lg transition-all ${view === v ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500 hover:text-slate-800'}`}>
              {v}
            </button>
          ))}
        </div>

        {view !== 'LIST' && (
          <div className="flex items-center gap-3">
            <button onClick={() => {
              const d = new Date(view === 'CALENDAR' ? viewDate : ganttBaseDate);
              d.setMonth(d.getMonth() - 1);
              view === 'CALENDAR' ? setViewDate(d) : setGanttBaseDate(d);
            }} className="p-2 bg-white border border-slate-200 rounded-lg text-xs">◀</button>
            <span className="text-xs font-bold text-slate-700 min-w-[80px] text-center">
              {view === 'CALENDAR' ? `${viewDate.getFullYear()}.${viewDate.getMonth()+1}` : `${ganttBaseDate.getFullYear()}`}
            </span>
            <button onClick={() => {
              const d = new Date(view === 'CALENDAR' ? viewDate : ganttBaseDate);
              d.setMonth(d.getMonth() + 1);
              view === 'CALENDAR' ? setViewDate(d) : setGanttBaseDate(d);
            }} className="p-2 bg-white border border-slate-200 rounded-lg text-xs">▶</button>
          </div>
        )}

        <button onClick={openAddModal} className="w-full sm:w-auto px-4 py-2.5 bg-blue-600 text-white text-[11px] font-bold rounded-xl shadow-lg shadow-blue-100">+ 추가</button>
      </div>

      <div className="p-4 overflow-x-auto min-h-[400px]">
        {view === 'LIST' && (
          <table className="w-full text-left min-w-[500px]">
            <thead>
              <tr className="text-[10px] text-slate-400 font-black uppercase tracking-widest border-b border-slate-50">
                <th className="pb-3 px-2">태스크</th>
                <th className="pb-3 px-2 text-center">상태</th>
                <th className="pb-3 px-2 text-right">기한</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {milestones.map(m => (
                <tr key={m.id} onClick={() => openEditModal(m)} className="text-sm group hover:bg-slate-50 cursor-pointer transition-colors">
                  <td className="py-4 px-2 font-bold text-slate-700">{m.title}</td>
                  <td className="py-4 px-2 text-center">
                    <span className={`px-2 py-0.5 rounded text-[10px] font-bold ${m.status === 'COMPLETED' ? 'bg-green-100 text-green-700' : m.status === 'OVERDUE' ? 'bg-red-100 text-red-700' : 'bg-blue-100 text-blue-700'}`}>{m.status}</span>
                  </td>
                  <td className="py-4 px-2 text-right text-[11px] font-mono text-slate-400">{m.startDate} ~ {m.endDate}</td>
                </tr>
              ))}
              {milestones.length === 0 && (
                <tr>
                  <td colSpan={3} className="py-12 text-center text-slate-400 italic text-sm">등록된 마일스톤이 없습니다.</td>
                </tr>
              )}
            </tbody>
          </table>
        )}

        {view === 'CALENDAR' && (
           <div className="min-w-[700px]">
             <div className="grid grid-cols-7 gap-1">
               {['SUN', 'MON', 'TUE', 'WED', 'THU', 'FRI', 'SAT'].map(d => <div key={d} className="text-center text-[10px] font-black text-slate-400 py-2 uppercase">{d}</div>)}
               {calendarDates.map((date, i) => (
                 <div key={i} className={`bg-slate-50/50 min-h-[100px] p-2 rounded-xl border border-white transition-all hover:bg-white hover:shadow-sm ${date.getMonth() !== viewDate.getMonth() ? 'opacity-30' : ''}`}>
                    <span className="text-[10px] font-bold text-slate-500">{date.getDate()}</span>
                    <div className="mt-1 space-y-1">
                      {milestones.map(m => {
                        const mS = new Date(m.startDate); const mE = new Date(m.endDate);
                        if (date >= mS && date <= mE) return <div key={m.id} onClick={() => openEditModal(m)} className="p-1 text-[8px] font-bold bg-blue-500 text-white rounded truncate cursor-pointer hover:bg-blue-600">{m.title}</div>;
                        return null;
                      })}
                    </div>
                 </div>
               ))}
             </div>
           </div>
        )}

        {view === 'GANTT' && (
           <div className="min-w-[800px] space-y-6">
             <div className="flex border-b border-slate-100 bg-slate-50 p-2 rounded-xl">
               <div className="w-40 text-[10px] font-black text-slate-400">Task Name</div>
               <div className="flex-1 flex justify-around">
                 {ganttConfig.units.map((u, i) => <span key={i} className="text-[9px] font-bold text-slate-400">{u}</span>)}
               </div>
             </div>
             {milestones.map(m => (
               <div key={m.id} className="flex items-center gap-4 cursor-pointer group" onClick={() => openEditModal(m)}>
                 <div className="w-40 truncate text-sm font-bold text-slate-700 group-hover:text-blue-600">{m.title}</div>
                 <div className="flex-1 h-8 bg-slate-50 rounded-lg relative overflow-hidden border border-slate-100 shadow-inner">
                   <div className={`absolute h-full bg-blue-500 rounded-lg flex items-center px-2 text-[9px] text-white font-bold shadow-md hover:bg-blue-600 transition-colors`} style={calculateGanttStyle(m)}>{m.title}</div>
                 </div>
               </div>
             ))}
           </div>
        )}
      </div>

      {/* Basic Modal Implementation */}
      {(showAdd || editingMilestone) && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[100] flex items-center justify-center p-4">
          <div className="bg-white rounded-3xl w-full max-w-sm overflow-hidden shadow-2xl animate-scaleIn">
            <div className="p-6 border-b border-slate-50 flex justify-between items-center bg-slate-50">
              <h3 className="font-bold text-slate-800">{editingMilestone ? '마일스톤 수정' : '마일스톤 추가'}</h3>
              <button onClick={() => {setShowAdd(false); setEditingMilestone(null);}} className="text-slate-400 p-2 hover:bg-slate-200 rounded-full transition-colors">✕</button>
            </div>
            <div className="p-6 space-y-4">
              <div className="space-y-1.5">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">태스크명</label>
                <input value={formTitle} onChange={e => setFormTitle(e.target.value)} className="w-full p-3 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-blue-500 transition-shadow" placeholder="태스크명을 입력하세요" />
              </div>
              <div className="grid grid-cols-2 gap-3">
                <div className="space-y-1.5">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">시작일</label>
                  <input type="date" value={formStart} onChange={e => setFormStart(e.target.value)} className="w-full p-2 border border-slate-200 rounded-lg text-xs" />
                </div>
                <div className="space-y-1.5">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">종료일</label>
                  <input type="date" value={formEnd} onChange={e => setFormEnd(e.target.value)} className="w-full p-2 border border-slate-200 rounded-lg text-xs" />
                </div>
              </div>
              {editingMilestone && (
                <div className="space-y-1.5">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">상태</label>
                  <select value={formStatus} onChange={e => setFormStatus(e.target.value as any)} className="w-full p-2.5 border border-slate-200 rounded-xl text-sm bg-slate-50">
                    <option value="UPCOMING">진행 예정 (UPCOMING)</option>
                    <option value="COMPLETED">완료 (COMPLETED)</option>
                    <option value="OVERDUE">지연 (OVERDUE)</option>
                  </select>
                </div>
              )}
              <div className="pt-2 space-y-2">
                <button 
                  onClick={editingMilestone ? handleSaveEdit : handleAdd} 
                  className="w-full py-3 bg-blue-600 text-white rounded-xl font-bold hover:bg-blue-700 transition-colors shadow-lg shadow-blue-100"
                >
                  {editingMilestone ? '업데이트' : '확인'}
                </button>
                {editingMilestone && (
                  <button 
                    onClick={() => handleDelete(editingMilestone.id)} 
                    className="w-full py-2 text-xs text-red-500 font-bold hover:bg-red-50 rounded-lg transition-colors"
                  >
                    삭제하기
                  </button>
                )}
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { Project } from '../types';

interface SidebarProps {
  projects: Project[];
  selectedId: string | null;
  onSelectProject: (id: string | null) => void;
  onNavigate: (view: 'DASHBOARD' | 'SETTINGS') => void;
  isOpen: boolean;
  onClose: () => void;
}

export const Sidebar: React.FC<SidebarProps> = ({ projects, selectedId, onSelectProject, onNavigate, isOpen, onClose }) => {
  // 섹션 확장/축소 상태 관리
  const [expandedSections, setExpandedSections] = useState<Record<string, boolean>>({
    TODO: true,
    IN_PROGRESS: true,
    DONE: false
  });

  const toggleSection = (section: string) => {
    setExpandedSections(prev => ({ ...prev, [section]: !prev[section] }));
  };

  // 프로젝트 그룹화 로직
  const groupedProjects = useMemo(() => {
    const groups: Record<string, Project[]> = {
      TODO: [],
      IN_PROGRESS: [],
      DONE: [],
      OTHER: []
    };

    projects.forEach(p => {
      const s1 = p.status1.toUpperCase();
      if (s1.includes('TODO') || s1.includes('대기')) groups.TODO.push(p);
      else if (s1.includes('PROGRESS') || s1.includes('진행')) groups.IN_PROGRESS.push(p);
      else if (s1.includes('DONE') || s1.includes('완료')) groups.DONE.push(p);
      else groups.OTHER.push(p);
    });

    return groups;
  }, [projects]);

  // 진행 중인 프로젝트를 2단계 상태별로 재그룹화
  const inProgressSubGroups = useMemo(() => {
    const sub: Record<string, Project[]> = {};
    groupedProjects.IN_PROGRESS.forEach(p => {
      if (!sub[p.status2]) sub[p.status2] = [];
      sub[p.status2].push(p);
    });
    return sub;
  }, [groupedProjects.IN_PROGRESS]);

  const renderProjectItem = (p: Project) => (
    <button
      key={p.id}
      onClick={() => onSelectProject(p.id)}
      className={`w-full text-left px-3 py-2 rounded-lg transition-all text-xs truncate flex items-center gap-2 group/item ${
        selectedId === p.id 
          ? 'bg-blue-600 text-white shadow-md' 
          : 'hover:bg-slate-800 text-slate-400 hover:text-slate-200'
      }`}
    >
      <span className={`w-1.5 h-1.5 rounded-full shrink-0 ${selectedId === p.id ? 'bg-white' : 'bg-slate-600 group-hover/item:bg-slate-400'}`} />
      <span className="truncate flex-1">{p.name}</span>
      {selectedId !== p.id && <span className="text-[9px] opacity-0 group-hover/item:opacity-100 text-slate-500">보기</span>}
    </button>
  );

  return (
    <>
      {/* Overlay for mobile */}
      {isOpen && (
        <div 
          className="fixed inset-0 bg-black/60 z-[55] lg:hidden backdrop-blur-sm transition-opacity"
          onClick={onClose}
        />
      )}

      <div className={`
        fixed left-0 top-0 bottom-0 w-64 bg-slate-900 text-white z-[60] flex flex-col transition-transform duration-300 ease-in-out border-r border-slate-800
        ${isOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}
      `}>
        <div className="p-6 border-b border-slate-800 flex justify-between items-center">
          <div className="flex items-center gap-2">
            <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center font-black text-xl">P</div>
            <h1 className="text-lg font-bold tracking-tight">PM Master</h1>
          </div>
          <button onClick={onClose} className="lg:hidden text-slate-400 p-2 hover:bg-slate-800 rounded-md">✕</button>
        </div>

        <nav className="flex-1 overflow-y-auto py-4 px-3 space-y-6 custom-scrollbar">
          {/* Main Navigation */}
          <div className="space-y-1">
            <button 
              onClick={() => onNavigate('DASHBOARD')}
              className="w-full text-left px-4 py-3 rounded-xl transition hover:bg-slate-800 flex items-center gap-3 text-sm font-bold group"
            >
              <span className="text-lg group-hover:scale-110 transition-transform">📊</span> 
              <span className="text-slate-300 group-hover:text-white">통합 대시보드</span>
            </button>
          </div>

          {/* Projects Grouped by Status */}
          <div className="space-y-4">
            {/* 1. TODO Section */}
            <div>
              <button 
                onClick={() => toggleSection('TODO')}
                className="w-full flex items-center justify-between px-3 mb-2 text-[10px] font-black text-slate-500 uppercase tracking-[0.15em] hover:text-slate-300 transition-colors"
              >
                <span className="flex items-center gap-2">
                  <span className="w-1.5 h-1.5 rounded-full bg-slate-500" />
                  진행 대기 ({groupedProjects.TODO.length})
                </span>
                <span>{expandedSections.TODO ? '▾' : '▸'}</span>
              </button>
              {expandedSections.TODO && (
                <div className="space-y-0.5 ml-2 animate-fadeIn">
                  {groupedProjects.TODO.map(renderProjectItem)}
                  {groupedProjects.TODO.length === 0 && <div className="px-4 py-2 text-[10px] text-slate-600 italic">대기중인 프로젝트 없음</div>}
                </div>
              )}
            </div>

            {/* 2. IN PROGRESS Section (with Sub-groups) */}
            <div>
              <button 
                onClick={() => toggleSection('IN_PROGRESS')}
                className="w-full flex items-center justify-between px-3 mb-2 text-[10px] font-black text-blue-400 uppercase tracking-[0.15em] hover:text-blue-300 transition-colors"
              >
                <span className="flex items-center gap-2">
                  <span className="w-1.5 h-1.5 rounded-full bg-blue-500 animate-pulse" />
                  실시간 진행 중 ({groupedProjects.IN_PROGRESS.length})
                </span>
                <span>{expandedSections.IN_PROGRESS ? '▾' : '▸'}</span>
              </button>
              {expandedSections.IN_PROGRESS && (
                <div className="space-y-4 ml-2 animate-fadeIn">
                  {/* Explicitly cast Object.entries to fix 'unknown' type error */}
                  {(Object.entries(inProgressSubGroups) as [string, Project[]][]).map(([status2, projs]) => (
                    <div key={status2} className="space-y-1">
                      <div className="px-3 py-1 flex justify-between items-center bg-slate-800/40 rounded-md mb-1">
                        <span className="text-[9px] font-bold text-slate-400">{status2}</span>
                        <span className="text-[9px] font-bold text-slate-500">{projs.length}</span>
                      </div>
                      <div className="space-y-0.5">
                        {projs.map(renderProjectItem)}
                      </div>
                    </div>
                  ))}
                  {groupedProjects.IN_PROGRESS.length === 0 && <div className="px-4 py-2 text-[10px] text-slate-600 italic">진행 중인 프로젝트 없음</div>}
                </div>
              )}
            </div>

            {/* 3. DONE Section */}
            <div>
              <button 
                onClick={() => toggleSection('DONE')}
                className="w-full flex items-center justify-between px-3 mb-2 text-[10px] font-black text-green-500 uppercase tracking-[0.15em] hover:text-green-300 transition-colors"
              >
                <span className="flex items-center gap-2">
                  <span className="w-1.5 h-1.5 rounded-full bg-green-500" />
                  완료된 프로젝트 ({groupedProjects.DONE.length})
                </span>
                <span>{expandedSections.DONE ? '▾' : '▸'}</span>
              </button>
              {expandedSections.DONE && (
                <div className="space-y-0.5 ml-2 animate-fadeIn">
                  {groupedProjects.DONE.map(renderProjectItem)}
                  {groupedProjects.DONE.length === 0 && <div className="px-4 py-2 text-[10px] text-slate-600 italic">완료된 프로젝트 없음</div>}
                </div>
              )}
            </div>
          </div>
        </nav>

        <div className="p-4 border-t border-slate-800">
          <button 
            onClick={() => onNavigate('SETTINGS')}
            className="w-full text-left px-4 py-3 rounded-xl transition hover:bg-slate-800 flex items-center gap-3 text-slate-400 text-sm font-medium group"
          >
            <span className="group-hover:rotate-45 transition-transform">⚙️</span> 
            <span className="group-hover:text-slate-200">워크플로우 구성</span>
          </button>
        </div>
      </div>
    </>
  );
};

import React, { useState, useMemo } from 'react';
import { Milestone, ViewType, ScaleType } from '../types';

interface MilestoneViewProps {
  milestones: Milestone[];
  onUpdateMilestones: (milestones: Milestone[]) => void;
}

export const MilestoneView: React.FC<MilestoneViewProps> = ({ milestones, onUpdateMilestones }) => {
  const [view, setView] = useState<ViewType>('LIST');
  const [scale, setScale] = useState<ScaleType>('MONTH');
  const [viewDate, setViewDate] = useState(new Date());
  const [ganttBaseDate, setGanttBaseDate] = useState(new Date());
  const [showAdd, setShowAdd] = useState(false);
  const [editingMilestone, setEditingMilestone] = useState<Milestone | null>(null);

  const [formTitle, setFormTitle] = useState('');
  const [formStart, setFormStart] = useState('');
  const [formEnd, setFormEnd] = useState('');
  const [formStatus, setFormStatus] = useState<Milestone['status']>('UPCOMING');

  const openAddModal = () => { 
    setFormTitle(''); 
    setFormStart(''); 
    setFormEnd(''); 
    setFormStatus('UPCOMING'); 
    setShowAdd(true); 
  };

  const openEditModal = (m: Milestone) => { 
    setEditingMilestone(m); 
    setFormTitle(m.title); 
    setFormStart(m.startDate); 
    setFormEnd(m.endDate); 
    setFormStatus(m.status); 
  };

  const handleAdd = () => {
    if (!formTitle || !formStart || !formEnd) {
      alert('모든 필드를 입력해주세요.');
      return;
    }
    const newMilestone: Milestone = { 
      id: Math.random().toString(36).substr(2, 9), 
      title: formTitle, 
      startDate: formStart, 
      endDate: formEnd, 
      status: 'UPCOMING' 
    };
    onUpdateMilestones([...milestones, newMilestone]);
    setShowAdd(false);
  };

  const handleSaveEdit = () => {
    if (!editingMilestone) return;
    const updatedList = milestones.map(m => 
      m.id === editingMilestone.id 
        ? { ...m, title: formTitle, startDate: formStart, endDate: formEnd, status: formStatus } 
        : m
    );
    onUpdateMilestones(updatedList);
    setEditingMilestone(null);
  };

  const handleDelete = (e: React.MouseEvent, id: string) => {
    e.stopPropagation(); // 이벤트 전파 방지
    if (window.confirm('이 마일스톤을 삭제하시겠습니까?')) {
      const filteredList = milestones.filter(m => m.id !== id);
      onUpdateMilestones(filteredList);
      setEditingMilestone(null); // 삭제 후 반드시 모달 닫기
    }
  };

  const calendarDates = useMemo(() => {
    const start = new Date(viewDate.getFullYear(), viewDate.getMonth(), 1);
    const startDay = start.getDay();
    const startDate = new Date(start);
    startDate.setDate(start.getDate() - startDay);
    return Array.from({ length: 42 }).map((_, i) => {
      const d = new Date(startDate);
      d.setDate(startDate.getDate() + i);
      return d;
    });
  }, [viewDate]);

  const ganttConfig = useMemo(() => {
    let units = [];
    let startRange: Date, endRange: Date;
    if (scale === 'DAY') {
      startRange = new Date(ganttBaseDate); startRange.setHours(0,0,0,0);
      for (let i = 0; i < 14; i++) { const d = new Date(startRange); d.setDate(startRange.getDate() + i); units.push(`${d.getMonth()+1}/${d.getDate()}`); }
      endRange = new Date(startRange); endRange.setDate(startRange.getDate() + 14);
    } else if (scale === 'MONTH') {
      startRange = new Date(ganttBaseDate.getFullYear(), 0, 1);
      for (let i = 1; i <= 12; i++) units.push(`${i}월`);
      endRange = new Date(ganttBaseDate.getFullYear(), 11, 31);
    } else {
      startRange = new Date(ganttBaseDate.getFullYear(), 0, 1);
      for (let i = 1; i <= 4; i++) units.push(`${i}Q`);
      endRange = new Date(ganttBaseDate.getFullYear(), 11, 31);
    }
    return { units, startRange, endRange };
  }, [scale, ganttBaseDate]);

  const calculateGanttStyle = (m: Milestone) => {
    const { startRange, endRange } = ganttConfig;
    const mStart = new Date(m.startDate); const mEnd = new Date(m.endDate);
    const total = endRange.getTime() - startRange.getTime();
    let left = ((mStart.getTime() - startRange.getTime()) / total) * 100;
    let width = ((mEnd.getTime() - mStart.getTime()) / total) * 100;
    if (left + width < 0 || left > 100) return { display: 'none' };
    return { left: `${Math.max(0, left)}%`, width: `${Math.min(100, width)}%` };
  };

  return (
    <div className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden flex flex-col">
      {/* Controls Bar */}
      <div className="p-4 border-b border-slate-100 bg-slate-50/50 flex flex-col sm:flex-row justify-between items-center gap-4">
        <div className="flex bg-slate-200/50 p-1 rounded-xl w-full sm:w-auto">
          {(['LIST', 'CALENDAR', 'GANTT'] as ViewType[]).map(v => (
            <button key={v} onClick={() => setView(v)} className={`flex-1 px-4 py-2 text-[11px] font-bold rounded-lg transition-all ${view === v ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500 hover:text-slate-800'}`}>
              {v}
            </button>
          ))}
        </div>

        {view !== 'LIST' && (
          <div className="flex items-center gap-3">
            <button onClick={() => {
              const d = new Date(view === 'CALENDAR' ? viewDate : ganttBaseDate);
              d.setMonth(d.getMonth() - 1);
              view === 'CALENDAR' ? setViewDate(d) : setGanttBaseDate(d);
            }} className="p-2 bg-white border border-slate-200 rounded-lg text-xs hover:bg-slate-100 transition-colors">◀</button>
            <span className="text-xs font-bold text-slate-700 min-w-[80px] text-center">
              {view === 'CALENDAR' ? `${viewDate.getFullYear()}.${viewDate.getMonth()+1}` : `${ganttBaseDate.getFullYear()}`}
            </span>
            <button onClick={() => {
              const d = new Date(view === 'CALENDAR' ? viewDate : ganttBaseDate);
              d.setMonth(d.getMonth() + 1);
              view === 'CALENDAR' ? setViewDate(d) : setGanttBaseDate(d);
            }} className="p-2 bg-white border border-slate-200 rounded-lg text-xs hover:bg-slate-100 transition-colors">▶</button>
          </div>
        )}

        <button onClick={openAddModal} className="w-full sm:w-auto px-4 py-2.5 bg-blue-600 text-white text-[11px] font-bold rounded-xl shadow-lg shadow-blue-100 hover:bg-blue-700 transition-all">+ 추가</button>
      </div>

      <div className="p-4 overflow-x-auto min-h-[400px]">
        {view === 'LIST' && (
          <table className="w-full text-left min-w-[500px]">
            <thead>
              <tr className="text-[10px] text-slate-400 font-black uppercase tracking-widest border-b border-slate-50">
                <th className="pb-3 px-2">태스크</th>
                <th className="pb-3 px-2 text-center">상태</th>
                <th className="pb-3 px-2 text-right">기한</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {milestones.map(m => (
                <tr key={m.id} onClick={() => openEditModal(m)} className="text-sm group hover:bg-slate-50 cursor-pointer transition-colors">
                  <td className="py-4 px-2 font-bold text-slate-700">{m.title}</td>
                  <td className="py-4 px-2 text-center">
                    <span className={`px-2 py-0.5 rounded text-[10px] font-bold ${m.status === 'COMPLETED' ? 'bg-green-100 text-green-700' : m.status === 'OVERDUE' ? 'bg-red-100 text-red-700' : 'bg-blue-100 text-blue-700'}`}>{m.status}</span>
                  </td>
                  <td className="py-4 px-2 text-right text-[11px] font-mono text-slate-400">{m.startDate} ~ {m.endDate}</td>
                </tr>
              ))}
              {milestones.length === 0 && (
                <tr>
                  <td colSpan={3} className="py-12 text-center text-slate-400 italic text-sm">등록된 마일스톤이 없습니다.</td>
                </tr>
              )}
            </tbody>
          </table>
        )}

        {view === 'CALENDAR' && (
           <div className="min-w-[700px]">
             <div className="grid grid-cols-7 gap-1">
               {['SUN', 'MON', 'TUE', 'WED', 'THU', 'FRI', 'SAT'].map(d => <div key={d} className="text-center text-[10px] font-black text-slate-400 py-2 uppercase">{d}</div>)}
               {calendarDates.map((date, i) => (
                 <div key={i} className={`bg-slate-50/50 min-h-[100px] p-2 rounded-xl border border-white transition-all hover:bg-white hover:shadow-sm ${date.getMonth() !== viewDate.getMonth() ? 'opacity-30' : ''}`}>
                    <span className="text-[10px] font-bold text-slate-500">{date.getDate()}</span>
                    <div className="mt-1 space-y-1">
                      {milestones.map(m => {
                        const mS = new Date(m.startDate); const mE = new Date(m.endDate);
                        if (date >= mS && date <= mE) return <div key={m.id} onClick={() => openEditModal(m)} className="p-1 text-[8px] font-bold bg-blue-500 text-white rounded truncate cursor-pointer hover:bg-blue-600 transition-colors">{m.title}</div>;
                        return null;
                      })}
                    </div>
                 </div>
               ))}
             </div>
           </div>
        )}

        {view === 'GANTT' && (
           <div className="min-w-[800px] space-y-6">
             <div className="flex border-b border-slate-100 bg-slate-50 p-2 rounded-xl">
               <div className="w-40 text-[10px] font-black text-slate-400">Task Name</div>
               <div className="flex-1 flex justify-around">
                 {ganttConfig.units.map((u, i) => <span key={i} className="text-[9px] font-bold text-slate-400">{u}</span>)}
               </div>
             </div>
             {milestones.map(m => (
               <div key={m.id} className="flex items-center gap-4 cursor-pointer group" onClick={() => openEditModal(m)}>
                 <div className="w-40 truncate text-sm font-bold text-slate-700 group-hover:text-blue-600 transition-colors">{m.title}</div>
                 <div className="flex-1 h-8 bg-slate-50 rounded-lg relative overflow-hidden border border-slate-100 shadow-inner">
                   <div className={`absolute h-full bg-blue-500 rounded-lg flex items-center px-2 text-[9px] text-white font-bold shadow-md hover:bg-blue-600 transition-all`} style={calculateGanttStyle(m)}>{m.title}</div>
                 </div>
               </div>
             ))}
           </div>
        )}
      </div>

      {/* Basic Modal Implementation */}
      {(showAdd || editingMilestone) && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[100] flex items-center justify-center p-4">
          <div className="bg-white rounded-3xl w-full max-w-sm overflow-hidden shadow-2xl animate-scaleIn">
            <div className="p-6 border-b border-slate-50 flex justify-between items-center bg-slate-50">
              <h3 className="font-bold text-slate-800">{editingMilestone ? '마일스톤 수정' : '마일스톤 추가'}</h3>
              <button 
                type="button"
                onClick={() => {setShowAdd(false); setEditingMilestone(null);}} 
                className="text-slate-400 p-2 hover:bg-slate-200 rounded-full transition-colors"
              >✕</button>
            </div>
            <div className="p-6 space-y-4">
              <div className="space-y-1.5">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">태스크명</label>
                <input value={formTitle} onChange={e => setFormTitle(e.target.value)} className="w-full p-3 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-blue-500 transition-shadow" placeholder="태스크명을 입력하세요" />
              </div>
              <div className="grid grid-cols-2 gap-3">
                <div className="space-y-1.5">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">시작일</label>
                  <input type="date" value={formStart} onChange={e => setFormStart(e.target.value)} className="w-full p-2 border border-slate-200 rounded-lg text-xs" />
                </div>
                <div className="space-y-1.5">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">종료일</label>
                  <input type="date" value={formEnd} onChange={e => setFormEnd(e.target.value)} className="w-full p-2 border border-slate-200 rounded-lg text-xs" />
                </div>
              </div>
              {editingMilestone && (
                <div className="space-y-1.5">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">상태</label>
                  <select value={formStatus} onChange={e => setFormStatus(e.target.value as any)} className="w-full p-2.5 border border-slate-200 rounded-xl text-sm bg-slate-50 outline-none focus:ring-2 focus:ring-blue-500">
                    <option value="UPCOMING">진행 예정 (UPCOMING)</option>
                    <option value="COMPLETED">완료 (COMPLETED)</option>
                    <option value="OVERDUE">지연 (OVERDUE)</option>
                  </select>
                </div>
              )}
              <div className="pt-2 space-y-2">
                <button 
                  type="button"
                  onClick={editingMilestone ? handleSaveEdit : handleAdd} 
                  className="w-full py-3 bg-blue-600 text-white rounded-xl font-bold hover:bg-blue-700 transition-colors shadow-lg shadow-blue-100"
                >
                  {editingMilestone ? '업데이트' : '확인'}
                </button>
                {editingMilestone && (
                  <button 
                    type="button"
                    onClick={(e) => handleDelete(e, editingMilestone.id)} 
                    className="w-full py-2 text-xs text-red-500 font-bold hover:bg-red-50 rounded-lg transition-colors border border-transparent hover:border-red-100"
                  >
                    삭제하기
                  </button>
                )}
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { Milestone, ViewType, ScaleType } from '../types';

interface MilestoneViewProps {
  milestones: Milestone[];
  onUpdateMilestones: (milestones: Milestone[]) => void;
}

export const MilestoneView: React.FC<MilestoneViewProps> = ({ milestones, onUpdateMilestones }) => {
  const [view, setView] = useState<ViewType>('LIST');
  const [scale, setScale] = useState<ScaleType>('MONTH');
  const [viewDate, setViewDate] = useState(new Date());
  const [ganttBaseDate, setGanttBaseDate] = useState(new Date());
  const [showAdd, setShowAdd] = useState(false);
  const [editingMilestone, setEditingMilestone] = useState<Milestone | null>(null);

  const [formTitle, setFormTitle] = useState('');
  const [formStart, setFormStart] = useState('');
  const [formEnd, setFormEnd] = useState('');
  const [formStatus, setFormStatus] = useState<Milestone['status']>('UPCOMING');

  const openAddModal = () => { 
    setFormTitle(''); 
    setFormStart(''); 
    setFormEnd(''); 
    setFormStatus('UPCOMING'); 
    setShowAdd(true); 
  };

  const openEditModal = (m: Milestone) => { 
    setEditingMilestone(m); 
    setFormTitle(m.title); 
    setFormStart(m.startDate); 
    setFormEnd(m.endDate); 
    setFormStatus(m.status); 
  };

  const handleAdd = () => {
    if (!formTitle || !formStart || !formEnd) {
      alert('모든 필드를 입력해주세요.');
      return;
    }
    const newMilestone: Milestone = { 
      id: Math.random().toString(36).substr(2, 9), 
      title: formTitle, 
      startDate: formStart, 
      endDate: formEnd, 
      status: 'UPCOMING' 
    };
    onUpdateMilestones([...milestones, newMilestone]);
    setShowAdd(false);
  };

  const handleSaveEdit = () => {
    if (!editingMilestone) return;
    const updatedList = milestones.map(m => 
      m.id === editingMilestone.id 
        ? { ...m, title: formTitle, startDate: formStart, endDate: formEnd, status: formStatus } 
        : m
    );
    onUpdateMilestones(updatedList);
    setEditingMilestone(null);
  };

  const handleDelete = (e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();

    if (!editingMilestone) return;

    // 브라우저 표준 confirm 대화상자 노출 확인
    const isConfirmed = confirm('이 마일스톤을 삭제하시겠습니까?');

    if (isConfirmed) {
      const targetId = editingMilestone.id;
      const filteredList = milestones.filter(m => m.id !== targetId);
      onUpdateMilestones(filteredList);
      setEditingMilestone(null); // 삭제 후 모달 닫기
    }
  };

  const calendarDates = useMemo(() => {
    const start = new Date(viewDate.getFullYear(), viewDate.getMonth(), 1);
    const startDay = start.getDay();
    const startDate = new Date(start);
    startDate.setDate(start.getDate() - startDay);
    return Array.from({ length: 42 }).map((_, i) => {
      const d = new Date(startDate);
      d.setDate(startDate.getDate() + i);
      return d;
    });
  }, [viewDate]);

  const ganttConfig = useMemo(() => {
    let units = [];
    let startRange: Date, endRange: Date;
    if (scale === 'DAY') {
      startRange = new Date(ganttBaseDate); startRange.setHours(0,0,0,0);
      for (let i = 0; i < 14; i++) { const d = new Date(startRange); d.setDate(startRange.getDate() + i); units.push(`${d.getMonth()+1}/${d.getDate()}`); }
      endRange = new Date(startRange); endRange.setDate(startRange.getDate() + 14);
    } else if (scale === 'MONTH') {
      startRange = new Date(ganttBaseDate.getFullYear(), 0, 1);
      for (let i = 1; i <= 12; i++) units.push(`${i}월`);
      endRange = new Date(ganttBaseDate.getFullYear(), 11, 31);
    } else {
      startRange = new Date(ganttBaseDate.getFullYear(), 0, 1);
      for (let i = 1; i <= 4; i++) units.push(`${i}Q`);
      endRange = new Date(ganttBaseDate.getFullYear(), 11, 31);
    }
    return { units, startRange, endRange };
  }, [scale, ganttBaseDate]);

  const calculateGanttStyle = (m: Milestone) => {
    const { startRange, endRange } = ganttConfig;
    const mStart = new Date(m.startDate); const mEnd = new Date(m.endDate);
    const total = endRange.getTime() - startRange.getTime();
    let left = ((mStart.getTime() - startRange.getTime()) / total) * 100;
    let width = ((mEnd.getTime() - mStart.getTime()) / total) * 100;
    if (left + width < 0 || left > 100) return { display: 'none' };
    return { left: `${Math.max(0, left)}%`, width: `${Math.min(100, width)}%` };
  };

  return (
    <div className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden flex flex-col">
      {/* Controls Bar */}
      <div className="p-4 border-b border-slate-100 bg-slate-50/50 flex flex-col sm:flex-row justify-between items-center gap-4">
        <div className="flex bg-slate-200/50 p-1 rounded-xl w-full sm:w-auto">
          {(['LIST', 'CALENDAR', 'GANTT'] as ViewType[]).map(v => (
            <button key={v} onClick={() => setView(v)} className={`flex-1 px-4 py-2 text-[11px] font-bold rounded-lg transition-all ${view === v ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500 hover:text-slate-800'}`}>
              {v}
            </button>
          ))}
        </div>

        {view !== 'LIST' && (
          <div className="flex items-center gap-3">
            <button onClick={() => {
              const d = new Date(view === 'CALENDAR' ? viewDate : ganttBaseDate);
              d.setMonth(d.getMonth() - 1);
              view === 'CALENDAR' ? setViewDate(d) : setGanttBaseDate(d);
            }} className="p-2 bg-white border border-slate-200 rounded-lg text-xs hover:bg-slate-100 transition-colors">◀</button>
            <span className="text-xs font-bold text-slate-700 min-w-[80px] text-center">
              {view === 'CALENDAR' ? `${viewDate.getFullYear()}.${viewDate.getMonth()+1}` : `${ganttBaseDate.getFullYear()}`}
            </span>
            <button onClick={() => {
              const d = new Date(view === 'CALENDAR' ? viewDate : ganttBaseDate);
              d.setMonth(d.getMonth() + 1);
              view === 'CALENDAR' ? setViewDate(d) : setGanttBaseDate(d);
            }} className="p-2 bg-white border border-slate-200 rounded-lg text-xs hover:bg-slate-100 transition-colors">▶</button>
          </div>
        )}

        <button onClick={openAddModal} className="w-full sm:w-auto px-4 py-2.5 bg-blue-600 text-white text-[11px] font-bold rounded-xl shadow-lg shadow-blue-100 hover:bg-blue-700 transition-all">+ 추가</button>
      </div>

      <div className="p-4 overflow-x-auto min-h-[400px]">
        {view === 'LIST' && (
          <table className="w-full text-left min-w-[500px]">
            <thead>
              <tr className="text-[10px] text-slate-400 font-black uppercase tracking-widest border-b border-slate-50">
                <th className="pb-3 px-2">태스크</th>
                <th className="pb-3 px-2 text-center">상태</th>
                <th className="pb-3 px-2 text-right">기한</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {milestones.map(m => (
                <tr key={m.id} onClick={() => openEditModal(m)} className="text-sm group hover:bg-slate-50 cursor-pointer transition-colors">
                  <td className="py-4 px-2 font-bold text-slate-700">{m.title}</td>
                  <td className="py-4 px-2 text-center">
                    <span className={`px-2 py-0.5 rounded text-[10px] font-bold ${m.status === 'COMPLETED' ? 'bg-green-100 text-green-700' : m.status === 'OVERDUE' ? 'bg-red-100 text-red-700' : 'bg-blue-100 text-blue-700'}`}>{m.status}</span>
                  </td>
                  <td className="py-4 px-2 text-right text-[11px] font-mono text-slate-400">{m.startDate} ~ {m.endDate}</td>
                </tr>
              ))}
              {milestones.length === 0 && (
                <tr>
                  <td colSpan={3} className="py-12 text-center text-slate-400 italic text-sm">등록된 마일스톤이 없습니다.</td>
                </tr>
              )}
            </tbody>
          </table>
        )}

        {view === 'CALENDAR' && (
           <div className="min-w-[700px]">
             <div className="grid grid-cols-7 gap-1">
               {['SUN', 'MON', 'TUE', 'WED', 'THU', 'FRI', 'SAT'].map(d => <div key={d} className="text-center text-[10px] font-black text-slate-400 py-2 uppercase">{d}</div>)}
               {calendarDates.map((date, i) => (
                 <div key={i} className={`bg-slate-50/50 min-h-[100px] p-2 rounded-xl border border-white transition-all hover:bg-white hover:shadow-sm ${date.getMonth() !== viewDate.getMonth() ? 'opacity-30' : ''}`}>
                    <span className="text-[10px] font-bold text-slate-500">{date.getDate()}</span>
                    <div className="mt-1 space-y-1">
                      {milestones.map(m => {
                        const mS = new Date(m.startDate); const mE = new Date(m.endDate);
                        if (date >= mS && date <= mE) return <div key={m.id} onClick={() => openEditModal(m)} className="p-1 text-[8px] font-bold bg-blue-500 text-white rounded truncate cursor-pointer hover:bg-blue-600 transition-colors">{m.title}</div>;
                        return null;
                      })}
                    </div>
                 </div>
               ))}
             </div>
           </div>
        )}

        {view === 'GANTT' && (
           <div className="min-w-[800px] space-y-6">
             <div className="flex border-b border-slate-100 bg-slate-50 p-2 rounded-xl">
               <div className="w-40 text-[10px] font-black text-slate-400">Task Name</div>
               <div className="flex-1 flex justify-around">
                 {ganttConfig.units.map((u, i) => <span key={i} className="text-[9px] font-bold text-slate-400">{u}</span>)}
               </div>
             </div>
             {milestones.map(m => (
               <div key={m.id} className="flex items-center gap-4 cursor-pointer group" onClick={() => openEditModal(m)}>
                 <div className="w-40 truncate text-sm font-bold text-slate-700 group-hover:text-blue-600 transition-colors">{m.title}</div>
                 <div className="flex-1 h-8 bg-slate-50 rounded-lg relative overflow-hidden border border-slate-100 shadow-inner">
                   <div className={`absolute h-full bg-blue-500 rounded-lg flex items-center px-2 text-[9px] text-white font-bold shadow-md hover:bg-blue-600 transition-all`} style={calculateGanttStyle(m)}>{m.title}</div>
                 </div>
               </div>
             ))}
           </div>
        )}
      </div>

      {/* Basic Modal Implementation */}
      {(showAdd || editingMilestone) && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[100] flex items-center justify-center p-4">
          <div className="bg-white rounded-3xl w-full max-w-sm overflow-hidden shadow-2xl animate-scaleIn">
            <div className="p-6 border-b border-slate-50 flex justify-between items-center bg-slate-50">
              <h3 className="font-bold text-slate-800">{editingMilestone ? '마일스톤 수정' : '마일스톤 추가'}</h3>
              <button 
                type="button"
                onClick={() => {setShowAdd(false); setEditingMilestone(null);}} 
                className="text-slate-400 p-2 hover:bg-slate-200 rounded-full transition-colors"
              >✕</button>
            </div>
            <div className="p-6 space-y-4">
              <div className="space-y-1.5">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">태스크명</label>
                <input value={formTitle} onChange={e => setFormTitle(e.target.value)} className="w-full p-3 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-blue-500 transition-shadow" placeholder="태스크명을 입력하세요" />
              </div>
              <div className="grid grid-cols-2 gap-3">
                <div className="space-y-1.5">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">시작일</label>
                  <input type="date" value={formStart} onChange={e => setFormStart(e.target.value)} className="w-full p-2 border border-slate-200 rounded-lg text-xs" />
                </div>
                <div className="space-y-1.5">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">종료일</label>
                  <input type="date" value={formEnd} onChange={e => setFormEnd(e.target.value)} className="w-full p-2 border border-slate-200 rounded-lg text-xs" />
                </div>
              </div>
              {editingMilestone && (
                <div className="space-y-1.5">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">상태</label>
                  <select value={formStatus} onChange={e => setFormStatus(e.target.value as any)} className="w-full p-2.5 border border-slate-200 rounded-xl text-sm bg-slate-50 outline-none focus:ring-2 focus:ring-blue-500">
                    <option value="UPCOMING">진행 예정 (UPCOMING)</option>
                    <option value="COMPLETED">완료 (COMPLETED)</option>
                    <option value="OVERDUE">지연 (OVERDUE)</option>
                  </select>
                </div>
              )}
              <div className="pt-2 space-y-2">
                <button 
                  type="button"
                  onClick={editingMilestone ? handleSaveEdit : handleAdd} 
                  className="w-full py-3 bg-blue-600 text-white rounded-xl font-bold hover:bg-blue-700 transition-colors shadow-lg shadow-blue-100"
                >
                  {editingMilestone ? '업데이트' : '확인'}
                </button>
                {editingMilestone && (
                  <button 
                    type="button"
                    onClick={handleDelete} 
                    className="w-full py-2 text-xs text-red-500 font-bold hover:bg-red-50 rounded-lg transition-colors border border-transparent hover:border-red-100"
                  >
                    삭제하기
                  </button>
                )}
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState } from 'react';
import { Sidebar } from './components/Sidebar';
import { Dashboard } from './components/Dashboard';
import { ProjectDetail } from './components/ProjectDetail';
import { Settings } from './components/Settings';
import { AppState, Project } from './types';
import { MOCK_PROJECTS, INITIAL_STATUS1, INITIAL_STATUS2 } from './constants';

const App: React.FC = () => {
  const [state, setState] = useState<AppState>({
    projects: MOCK_PROJECTS as Project[],
    customStatus1: INITIAL_STATUS1,
    customStatus2: INITIAL_STATUS2,
    selectedProjectId: null,
    activeView: 'DASHBOARD'
  });

  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  const handleSelectProject = (id: string | null) => {
    setState(prev => ({ 
      ...prev, 
      selectedProjectId: id, 
      activeView: id ? 'PROJECT_DETAIL' : 'DASHBOARD' 
    }));
    setIsSidebarOpen(false); // 모바일에서 선택 시 닫기
  };

  const handleNavigate = (view: 'DASHBOARD' | 'SETTINGS') => {
    setState(prev => ({ 
      ...prev, 
      activeView: view, 
      selectedProjectId: null 
    }));
    setIsSidebarOpen(false); // 모바일에서 선택 시 닫기
  };

  const handleUpdateProject = (updated: Project) => {
    setState(prev => ({
      ...prev,
      projects: prev.projects.map(p => p.id === updated.id ? updated : p)
    }));
  };

  const handleDeleteProject = (id: string) => {
    if (confirm('이 프로젝트와 관련된 모든 데이터(마일스톤, 보고서 등)가 영구적으로 삭제됩니다. 계속하시겠습니까?')) {
      setState(prev => ({
        ...prev,
        projects: prev.projects.filter(p => p.id !== id),
        selectedProjectId: null,
        activeView: 'DASHBOARD'
      }));
    }
  };

  const handleUpdateStatus1 = (newList: string[]) => {
    setState(prev => ({ ...prev, customStatus1: newList }));
  };

  const handleUpdateStatus2 = (newList: string[]) => {
    setState(prev => ({ ...prev, customStatus2: newList }));
  };

  const selectedProject = state.projects.find(p => p.id === state.selectedProjectId);

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col lg:flex-row">
      {/* Mobile Header */}
      <div className="lg:hidden bg-slate-900 text-white p-4 flex justify-between items-center sticky top-0 z-50 shadow-md">
        <h1 className="font-bold">PM Master</h1>
        <button 
          onClick={() => setIsSidebarOpen(!isSidebarOpen)}
          className="p-2 hover:bg-slate-800 rounded"
        >
          {isSidebarOpen ? '✕' : '☰'}
        </button>
      </div>

      {/* Sidebar with Drawer Logic */}
      <Sidebar 
        projects={state.projects} 
        selectedId={state.selectedProjectId}
        onSelectProject={handleSelectProject}
        onNavigate={handleNavigate}
        isOpen={isSidebarOpen}
        onClose={() => setIsSidebarOpen(false)}
      />

      {/* Main Content Area */}
      <main className={`flex-1 transition-all duration-300 p-4 md:p-8 lg:p-12 lg:ml-64`}>
        <div className="max-w-7xl mx-auto">
          {state.activeView === 'DASHBOARD' && (
            <Dashboard 
              projects={state.projects} 
              status1List={state.customStatus1}
              status2List={state.customStatus2}
              onSelect={handleSelectProject} 
            />
          )}

          {state.activeView === 'PROJECT_DETAIL' && selectedProject && (
            <ProjectDetail 
              project={selectedProject} 
              onUpdate={handleUpdateProject}
              onDelete={handleDeleteProject}
              status1Options={state.customStatus1}
              status2Options={state.customStatus2}
            />
          )}

          {state.activeView === 'SETTINGS' && (
            <Settings 
              customStatus1={state.customStatus1}
              customStatus2={state.customStatus2} 
              onUpdate1={handleUpdateStatus1}
              onUpdate2={handleUpdateStatus2} 
            />
          )}
        </div>
      </main>

      {/* Floating Action Button */}
      {state.activeView === 'DASHBOARD' && (
        <button 
          onClick={() => {
            const newProj: Project = {
              id: Date.now().toString(),
              name: '신규 프로젝트 ' + (state.projects.length + 1),
              manager: '관리자',
              description: '설명을 입력해주세요.',
              status1: state.customStatus1[0],
              status2: state.customStatus2[0],
              startDate: new Date().toISOString().split('T')[0],
              endDate: new Date().toISOString().split('T')[0],
              milestones: [],
              weeklyReports: []
            };
            setState(prev => ({ ...prev, projects: [...prev.projects, newProj] }));
          }}
          className="fixed bottom-6 right-6 md:bottom-10 md:right-10 w-12 h-12 md:w-14 md:h-14 bg-blue-600 text-white rounded-full shadow-2xl hover:bg-blue-700 flex items-center justify-center text-2xl md:text-3xl font-light transition-transform hover:scale-110 active:scale-95 z-40"
        >
          +
        </button>
      )}
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { Project, Milestone, ViewType, ScaleType } from '../types';
import { MilestoneView } from './MilestoneView';
import { generateTemplate } from '../services/geminiService';
import { getStatus1Color } from '../constants';

interface ProjectDetailProps {
  project: Project;
  onUpdate: (updated: Project) => void;
  onDelete: (id: string) => void;
  status1Options: string[];
  status2Options: string[];
}

export const ProjectDetail: React.FC<ProjectDetailProps> = ({ project, onUpdate, onDelete, status1Options, status2Options }) => {
  const [activeTab, setActiveTab] = useState<'OVERVIEW' | 'MILESTONES' | 'CHARTER' | 'REPORT' | 'RETRO'>('OVERVIEW');
  const [isGenerating, setIsGenerating] = useState(false);
  const [isEditingHeader, setIsEditingHeader] = useState(false);

  const [editedName, setEditedName] = useState(project.name);
  const [editedDescription, setEditedDescription] = useState(project.description);
  const [editedManager, setEditedManager] = useState(project.manager);
  const [editedStartDate, setEditedStartDate] = useState(project.startDate);
  const [editedEndDate, setEditedEndDate] = useState(project.endDate);

  const handleStatusChange = (field: 'status1' | 'status2', val: string) => {
    onUpdate({ ...project, [field]: val });
  };

  const handleSaveHeader = () => {
    onUpdate({ ...project, name: editedName, description: editedDescription, manager: editedManager, startDate: editedStartDate, endDate: editedEndDate });
    setIsEditingHeader(false);
  };

  const handleAutoGenerate = async (type: any) => {
    setIsGenerating(true);
    const content = await generateTemplate(type, {
      name: project.name, description: project.description, status: `${project.status1} / ${project.status2}`
    });
    const fieldMap: any = { CHARTER: 'charter', REQUIREMENTS: 'requirements', RETROSPECTIVE: 'retrospective' };
    if (type === 'WEEKLY_REPORT') {
      const newReport = { id: Date.now().toString(), date: new Date().toISOString().split('T')[0], content };
      onUpdate({ ...project, weeklyReports: [newReport, ...project.weeklyReports] });
    } else {
      onUpdate({ ...project, [fieldMap[type]]: content });
    }
    setIsGenerating(false);
  };

